import 'dart:convert';

final List<Map<String, dynamic>> telcB2Models = List<Map<String, dynamic>>.from(json.decode(r'''[{"id":"telc-b2-1","titleAr":"نموذج 1 — العمل والمهنة","titleDe":"Modelltest 1 — Arbeit & Beruf","level":"B2","durationMin":165,"readingPassages":[{"id":"lese-1","titleDe":"Homeoffice: Chance oder Belastung?","textDe":"Seit der Corona-Pandemie ist das Arbeiten von zu Hause aus für viele Beschäftigte zur Selbstverständlichkeit geworden. Was vor wenigen Jahren noch als Privileg einzelner Berufsgruppen galt, ist heute Teil des Alltags. Doch während die einen die Vorteile schätzen — kein langer Arbeitsweg, mehr Zeit für die Familie, ungestörtes Arbeiten —, klagen andere über soziale Isolation, ständige Erreichbarkeit und die Schwierigkeit, Berufliches und Privates voneinander zu trennen.\n\nEine aktuelle Studie der Universität München zeigt, dass etwa 60 % der Befragten zumindest teilweise im Homeoffice arbeiten möchten. Allerdings wünschen sich nur 18 %, ausschließlich von zu Hause zu arbeiten. Die Mehrheit bevorzugt eine Mischform, das sogenannte hybride Arbeiten, bei dem zwei bis drei Tage pro Woche im Büro verbracht werden.\n\nArbeitgeber stehen dieser Entwicklung mit gemischten Gefühlen gegenüber. Einerseits sparen Unternehmen Bürokosten, andererseits fürchten sie um die Unternehmenskultur und den informellen Austausch zwischen den Mitarbeitenden. Hinzu kommt: Wer von zu Hause arbeitet, ist schwieriger zu kontrollieren — was viele Führungskräfte bis heute verunsichert.","questions":[{"id":"q1","promptDe":"Was ist laut Text die häufigste Wunschform der Beschäftigten?","options":[{"id":"a","de":"Vollständig im Homeoffice zu arbeiten."},{"id":"b","de":"Nur im Büro zu arbeiten."},{"id":"c","de":"Eine Mischung aus Homeoffice und Büro (hybrid)."},{"id":"d","de":"Gar nicht zu arbeiten."}],"correct":"c","explanationAr":"الإجابة (C): النصّ يقول صراحةً \"Die Mehrheit bevorzugt eine Mischform\" أي العمل الهجين (يومان-ثلاثة أيّام في المكتب). فقط 18% يريدون الـHomeoffice الكامل."},{"id":"q2","promptDe":"Welcher Nachteil des Homeoffice wird im Text genannt?","options":[{"id":"a","de":"Höhere Kosten für die Mitarbeiter."},{"id":"b","de":"Soziale Isolation und ständige Erreichbarkeit."},{"id":"c","de":"Schlechtere Internetverbindung."},{"id":"d","de":"Mehr Krankheitstage."}],"correct":"b","explanationAr":"الإجابة (B): النصّ يذكر بوضوح \"soziale Isolation, ständige Erreichbarkeit und die Schwierigkeit, Berufliches und Privates zu trennen\". هذه الـ3 نقاط هي الجانب السلبي في الفقرة الأولى."},{"id":"q3","promptDe":"Wie reagieren Arbeitgeber auf das Homeoffice?","options":[{"id":"a","de":"Sie unterstützen es bedingungslos."},{"id":"b","de":"Sie lehnen es vollständig ab."},{"id":"c","de":"Sie sehen sowohl Vor- als auch Nachteile."},{"id":"d","de":"Sie verbieten es seit der Pandemie."}],"correct":"c","explanationAr":"الإجابة (C): الجملة \"stehen dieser Entwicklung mit gemischten Gefühlen gegenüber\" تعني مشاعر مختلطة — إيجابيّة (توفير التكاليف) وسلبيّة (ضعف ثقافة الشركة + صعوبة المراقبة)."},{"id":"q4","promptDe":"Welcher Vorteil des Homeoffice für Unternehmen wird genannt?","options":[{"id":"a","de":"Bessere Kontrolle der Mitarbeiter."},{"id":"b","de":"Stärkere Unternehmenskultur."},{"id":"c","de":"Einsparung von Bürokosten."},{"id":"d","de":"Mehr Innovationen."}],"correct":"c","explanationAr":"الإجابة (C): \"Unternehmen sparen Bürokosten\" — هذه الفائدة الوحيدة المذكورة بوضوح في النصّ. الخيارات الأخرى مذكورة كمخاوف لا فوائد."},{"id":"q5","promptDe":"Wie viele Befragte möchten gar nicht im Homeoffice arbeiten?","options":[{"id":"a","de":"Etwa 60 %"},{"id":"b","de":"18 %"},{"id":"c","de":"Etwa 40 %"},{"id":"d","de":"Wird im Text nicht erwähnt."}],"correct":"c","explanationAr":"الإجابة (C): النصّ يقول 60% يريدون الـHomeoffice (جزئياً على الأقلّ). إذن الـ40% الباقية لا يريدونه أبداً. الحساب: 100 - 60 = 40."}]},{"id":"lese-2","titleDe":"Künstliche Intelligenz im Alltag","textDe":"Sprachassistenten, Übersetzungssoftware, automatische Empfehlungen beim Online-Shopping: Künstliche Intelligenz (KI) durchdringt unseren Alltag, ohne dass wir es immer bemerken. Während Befürworter der Technologie ihre vielen Möglichkeiten betonen, warnen Kritiker vor den Risiken, insbesondere im Bereich des Datenschutzes und der Arbeitsplätze.\n\nBefürworter argumentieren, dass KI repetitive Aufgaben übernehmen und Menschen so für kreative Tätigkeiten freisetzen kann. In der Medizin hilft KI, Krebs früher zu erkennen, in der Industrie können Roboter gefährliche Arbeiten ausführen, und im Verkehr versprechen autonome Fahrzeuge weniger Unfälle.\n\nKritiker hingegen weisen auf gravierende Probleme hin: Welche Daten sammeln KI-Systeme? Wer trägt die Verantwortung, wenn ein autonomes Auto einen Unfall verursacht? Und vor allem: Welche Berufe werden durch die Automatisierung verschwinden? Studien gehen davon aus, dass in den nächsten zwanzig Jahren bis zu 30 % der heutigen Arbeitsplätze in Industrieländern wegfallen oder sich grundlegend verändern werden.\n\nDabei zeigt sich: Die Entwicklung lässt sich nicht aufhalten. Entscheidend ist, wie Gesellschaften mit den Folgen umgehen — durch Bildung, Regulierung und sozialen Ausgleich.","questions":[{"id":"q6","promptDe":"Was sagt der Text über die Verbreitung von KI?","options":[{"id":"a","de":"KI wird nur in der Medizin verwendet."},{"id":"b","de":"KI ist überall im Alltag, oft unbemerkt."},{"id":"c","de":"KI ist in Deutschland verboten."},{"id":"d","de":"KI wird erst in Zukunft eingesetzt werden."}],"correct":"b","explanationAr":"الإجابة (B): \"durchdringt unseren Alltag, ohne dass wir es immer bemerken\" = منتشرة في حياتنا اليومية دون أن نلاحظ دائماً."},{"id":"q7","promptDe":"Welches Argument der Kritiker wird genannt?","options":[{"id":"a","de":"KI ist zu langsam."},{"id":"b","de":"KI ist zu teuer."},{"id":"c","de":"KI gefährdet Datenschutz und Arbeitsplätze."},{"id":"d","de":"KI macht keine Fortschritte."}],"correct":"c","explanationAr":"الإجابة (C): \"warnen Kritiker vor den Risiken, insbesondere im Bereich des Datenschutzes und der Arbeitsplätze\"."},{"id":"q8","promptDe":"Wie viele Arbeitsplätze könnten laut Studien betroffen sein?","options":[{"id":"a","de":"Bis zu 10 %"},{"id":"b","de":"Bis zu 30 %"},{"id":"c","de":"Bis zu 50 %"},{"id":"d","de":"70 %"}],"correct":"b","explanationAr":"الإجابة (B): النصّ يحدّد \"bis zu 30 %\" خلال العشرين سنة القادمة."},{"id":"q9","promptDe":"Was schlägt der Text als Lösung vor?","options":[{"id":"a","de":"KI vollständig zu verbieten."},{"id":"b","de":"Bildung, Regulierung und sozialen Ausgleich."},{"id":"c","de":"Die Entwicklung zu beschleunigen."},{"id":"d","de":"Nichts zu tun, weil sich nichts ändern wird."}],"correct":"b","explanationAr":"الإجابة (B): الفقرة الأخيرة: \"Entscheidend ist, wie Gesellschaften mit den Folgen umgehen — durch Bildung, Regulierung und sozialen Ausgleich\"."},{"id":"q10","promptDe":"Welcher Vorteil von KI in der Medizin wird genannt?","options":[{"id":"a","de":"Niedrigere Kosten"},{"id":"b","de":"Krebs früher erkennen"},{"id":"c","de":"Bessere Pflege im Alter"},{"id":"d","de":"Längeres Leben"}],"correct":"b","explanationAr":"الإجابة (B): \"In der Medizin hilft KI, Krebs früher zu erkennen\". الكشف المبكّر هو الفائدة الطبيّة المذكورة."}]}],"sprachbausteine":[{"id":"sb1","contextDe":"Sehr geheehrte Damen und Herren, ich bewerbe mich hiermit ___ die ausgeschriebene Stelle.","blank":"um/für/auf/an","options":[{"id":"a","de":"um"},{"id":"b","de":"für"},{"id":"c","de":"auf"},{"id":"d","de":"an"}],"correct":"a","explanationAr":"**sich bewerben um + Akkusativ** = يقدّم طلب توظيف لـ. هذا هو حرف الجرّ القياسي مع الفعل bewerben. (لا تخلط مع \"sich interessieren für\" أو \"fragen nach\")."},{"id":"sb2","contextDe":"Trotz ___ schlechten Wetters fand das Picknick statt.","blank":"Genitiv","options":[{"id":"a","de":"der"},{"id":"b","de":"des"},{"id":"c","de":"dem"},{"id":"d","de":"den"}],"correct":"b","explanationAr":"**trotz + Genitiv** = \"بالرغم من\". مع الاسم المذكّر/المحايد: trotz **des** schlechten Wetters. (Wetter محايد)."},{"id":"sb3","contextDe":"Wenn ich Zeit ___, würde ich öfter ins Theater gehen.","blank":"Konjunktiv II","options":[{"id":"a","de":"habe"},{"id":"b","de":"hätte"},{"id":"c","de":"haben würde"},{"id":"d","de":"hatte"}],"correct":"b","explanationAr":"**شرط افتراضي → Konjunktiv II**: hätte (وليس habe). القاعدة: في الجزء الشرطي (Wenn-Satz) نستخدم Konjunktiv II بنفس الزمن في الجزء الجوابي."},{"id":"sb4","contextDe":"Der Bericht, ___ ich gestern gelesen habe, war sehr interessant.","blank":"Relativpronomen","options":[{"id":"a","de":"der"},{"id":"b","de":"den"},{"id":"c","de":"dem"},{"id":"d","de":"dessen"}],"correct":"b","explanationAr":"**ضمير الموصول** يأخذ نفس جنس الاسم (der Bericht — مذكّر) لكن حالته تعتمد على دوره في الجملة الفرعيّة. هنا \"ich habe **ihn** gelesen\" → Akkusativ → **den**."},{"id":"sb5","contextDe":"Sie ist sehr fleißig, ___ sie immer Erfolg hat.","blank":"Konjunktion","options":[{"id":"a","de":"weshalb"},{"id":"b","de":"weil"},{"id":"c","de":"obwohl"},{"id":"d","de":"damit"}],"correct":"a","explanationAr":"**weshalb** = \"لذلك\" = ضمير وصل ظرفي يربط نتيجة بسبب. السبب: فلذلك. (weil = \"لأنّ\" يأتي في البداية، obwohl = \"رغم أنّ\" متناقض، damit = \"لكي\" غاية)."},{"id":"sb6","contextDe":"Es wird empfohlen, dass die Kinder genug Schlaf ___.","blank":"Konjunktiv I oder II","options":[{"id":"a","de":"haben"},{"id":"b","de":"bekommen"},{"id":"c","de":"kriegen"},{"id":"d","de":"erhalten"}],"correct":"b","explanationAr":"**genug Schlaf bekommen** = يحصل على ما يكفي من النوم — تعبير ثابت. (haben/erhalten نادراً ما تُستخدم مع Schlaf، kriegen عاميّة)."}],"schreiben":{"id":"schreiben-1","topicAr":"كتابة منشور رأي حول العمل من المنزل","topicDe":"Forumsbeitrag: Homeoffice — pro oder contra?","contextDe":"Sie haben in einem Online-Forum die folgende Diskussion gelesen: \"Sollten alle Arbeitnehmer das Recht auf Homeoffice haben?\" Schreiben Sie einen Beitrag (150–200 Wörter), in dem Sie:","bulletPoints":["Ihre Meinung deutlich äußern (Pro oder Contra).","Mindestens zwei Argumente nennen.","Ein Beispiel aus Ihrer eigenen Erfahrung anführen.","Einen Lösungsvorschlag machen."],"redemittel":["Meiner Meinung nach … / Ich bin der Auffassung, dass …","Einerseits …, andererseits …","Aus meiner Erfahrung kann ich sagen, dass …","Ein wichtiger Vorteil/Nachteil ist, …","Allerdings sollte man auch bedenken, dass …","Abschließend bin ich der Meinung, dass …","Ein guter Kompromiss wäre, …"],"sampleEssayDe":"Liebe Forumsmitglieder,\n\nich verfolge die Diskussion über das Recht auf Homeoffice mit großem Interesse. Meiner Meinung nach sollten Arbeitnehmer dieses Recht grundsätzlich erhalten — zumindest dort, wo es die Arbeit erlaubt.\n\nEinerseits ermöglicht das Homeoffice eine bessere Vereinbarkeit von Beruf und Familie. Aus meiner eigenen Erfahrung kann ich sagen, dass ich seit Beginn der Pandemie zwei Tage pro Woche von zu Hause arbeite. Dadurch spare ich täglich zwei Stunden Arbeitsweg und kann meine Kinder nachmittags von der Schule abholen.\n\nAndererseits ist es richtig, dass das Homeoffice nicht für jeden Beruf geeignet ist. In Pflegeberufen oder im Handwerk geht das schlicht nicht. Außerdem bevorzugen manche Menschen den persönlichen Austausch im Büro.\n\nEin guter Kompromiss wäre meines Erachtens das hybride Arbeitsmodell: zwei bis drei Tage Homeoffice, der Rest im Büro. So bleibt die Unternehmenskultur erhalten und gleichzeitig profitieren die Mitarbeiter von mehr Flexibilität.\n\nAbschließend bin ich der Meinung, dass jeder Arbeitnehmer das Recht haben sollte, mit dem Arbeitgeber über Homeoffice zu verhandeln.\n\n(187 Wörter)","sampleEssayAr":"أعزّائي أعضاء المنتدى،\n\nأتابع النقاش حول حقّ العمل من المنزل باهتمام بالغ. **برأيي**، يجب أن يحصل الموظّفون على هذا الحقّ مبدئياً — على الأقلّ في المهن التي تسمح بذلك.\n\n**من جهة**، يتيح العمل من المنزل توازناً أفضل بين العمل والعائلة. **من تجربتي الشخصيّة** أستطيع القول إنّني منذ بداية الجائحة أعمل يومين في الأسبوع من البيت. بذلك أوفّر يومياً ساعتين من الطريق وأستطيع أخذ أولادي من المدرسة بعد الظهر.\n\n**من جهة أخرى**، صحيح أنّ الـHomeoffice لا يناسب كلّ مهنة. في مهن التمريض أو الحرف اليدوية لا يمكن ببساطة. فضلاً عن ذلك، يفضّل بعض الناس التواصل المباشر في المكتب.\n\n**حلٌّ وسط جيّد** برأيي هو نموذج العمل الهجين: يومان أو ثلاثة من البيت، والباقي في المكتب. هكذا تبقى ثقافة الشركة محفوظة، وفي نفس الوقت يستفيد الموظّفون من مرونة أكبر.\n\n**في الختام، أرى** أنّ كلّ موظّف يجب أن يحقّ له التفاوض مع صاحب العمل حول الـHomeoffice."},"sprechen":[{"id":"sp1","partAr":"الجزء 1 — تقديم الذات","partDe":"Teil 1 — Sich vorstellen","topicAr":"قدّم نفسك (الاسم، العمر، البلد، المهنة، الأسرة، الهوايات).","topicDe":"Stellen Sie sich vor: Name, Alter, Herkunft, Beruf, Familie, Hobbys.","redemittel":["Mein Name ist … und ich komme aus …","Ich bin … Jahre alt und wohne seit … in …","Beruflich arbeite ich als … / Ich studiere …","In meiner Freizeit beschäftige ich mich gern mit …","Was meine Familie betrifft, …"],"sampleAnswerDe":"Mein Name ist Khaled Al-Hamwi und ich komme ursprünglich aus Syrien, aus einer Stadt namens Hama. Seit 2018 lebe ich in Deutschland, momentan in Berlin. Ich bin 32 Jahre alt und arbeite als Krankenpfleger in einem großen Krankenhaus.\n\nWas meine Familie betrifft: Ich bin verheiratet und habe zwei Kinder, einen Sohn von fünf und eine Tochter von drei Jahren.\n\nIn meiner Freizeit beschäftige ich mich gern mit Fußball — ich spiele in einem lokalen Verein — und ich lese viel, vor allem deutsche Literatur, weil das hilft, meine Sprachkenntnisse zu verbessern."},{"id":"sp2","partAr":"الجزء 2 — وصف صورة","partDe":"Teil 2 — Bildbeschreibung","topicAr":"صف صورة (مثلاً: مكتب مفتوح، عائلة في حديقة، مظاهرة، إلخ).","topicDe":"Beschreiben Sie ein Bild und äußern Sie Ihre Meinung dazu.","redemittel":["Auf dem Bild sehe ich …","Im Vordergrund / Hintergrund befindet sich …","Auf der linken/rechten Seite ist/sind …","Die Szene wirkt auf mich … (ruhig, lebendig, hektisch)","Ich vermute, dass …","Ich kann mir gut vorstellen, dass die Personen …"],"sampleAnswerDe":"Auf dem Bild sehe ich ein modernes Großraumbüro mit etwa zehn Arbeitsplätzen. Im Vordergrund sitzen drei junge Menschen — eine Frau und zwei Männer — an einem gemeinsamen Tisch und schauen auf einen großen Bildschirm. Sie scheinen ein Projekt zu besprechen.\n\nIm Hintergrund erkennt man weitere Schreibtische mit Computern. Die Atmosphäre wirkt auf mich konzentriert, aber gleichzeitig kollegial. Es gibt viele Pflanzen und große Fenster, was den Raum freundlich macht.\n\nMeiner Meinung nach zeigt das Bild eine moderne Arbeitsweise, bei der Teamarbeit eine zentrale Rolle spielt. Ich kann mir gut vorstellen, dass die Personen für ein Start-up oder eine Werbeagentur arbeiten."},{"id":"sp3","partAr":"الجزء 3 — مناقشة وحلّ مشكلة","partDe":"Teil 3 — Diskussion und Problemlösung","topicAr":"تناقش مع شريكك حول تنظيم احتفال نهاية السنة في الشركة. اقترحوا الحلول معاً.","topicDe":"Sie planen mit Ihrem Partner ein Firmenfest. Diskutieren Sie über: Datum, Ort, Essen, Programm. Treffen Sie eine gemeinsame Entscheidung.","redemittel":["Was halten Sie von …?","Mein Vorschlag wäre, …","Ich finde Ihre Idee gut, aber …","Wir könnten auch … in Betracht ziehen.","Wären Sie damit einverstanden, …?","Lassen Sie uns Folgendes vereinbaren: …"],"sampleAnswerDe":"A: Was halten Sie davon, das Firmenfest am 15. Dezember zu veranstalten?\n\nB: Klingt gut, aber ich finde, das ist zu kurz vor Weihnachten. Mein Vorschlag wäre der erste Dezember.\n\nA: Einverstanden. Und wo sollen wir feiern? Ich finde, ein Restaurant wäre eine gute Idee.\n\nB: Ich finde Ihre Idee gut, aber wir sind über fünfzig Personen. Vielleicht sollten wir lieber einen Saal mieten und einen Caterer beauftragen.\n\nA: Da haben Sie Recht. Wären Sie damit einverstanden, dass wir den Saal im Hotel \"Zur Linde\" nehmen?\n\nB: Ja, das wäre perfekt. Lassen Sie uns Folgendes vereinbaren: Sie kümmern sich um den Saal, ich um das Catering."}]},{"id":"telc-b2-2","titleAr":"نموذج 2 — البيئة والاستدامة","titleDe":"Modelltest 2 — Umwelt & Nachhaltigkeit","level":"B2","durationMin":165,"readingPassages":[{"id":"lese-1","titleDe":"Plastikmüll in den Weltmeeren","textDe":"Jedes Jahr landen schätzungsweise acht Millionen Tonnen Plastikmüll in den Weltmeeren. Das entspricht einem Müllwagen voller Plastik pro Minute. Die Folgen sind dramatisch: Meerestiere verheddern sich in Netzen, verwechseln Plastiktüten mit Nahrung oder sterben an den Giftstoffen, die das Material freisetzt. Auch für den Menschen ist die Belastung längst spürbar, denn Mikroplastik wurde inzwischen in Trinkwasser, Salz und sogar im menschlichen Blut nachgewiesen.\n\nWissenschaftler warnen, dass sich bis zum Jahr 2050 mehr Plastik als Fische in den Ozeanen befinden könnte, wenn sich nichts ändert. Der Großteil des Mülls stammt nicht aus den Industriestaaten, sondern aus Ländern, in denen die Abfallwirtschaft unzureichend entwickelt ist. Flüsse wie der Jangtse oder der Ganges gelten als Hauptverkehrswege für Plastik ins Meer.\n\nDie Europäische Union hat bereits reagiert und seit 2021 Einwegprodukte aus Plastik wie Strohhalme, Wattestäbchen und Besteck verboten. Umweltschutzorganisationen begrüßen solche Schritte, fordern aber, dass auch die Produktion selbst reduziert werden müsse. Denn das eigentliche Problem, so die Kritiker, beginnt nicht beim Verbraucher, sondern bei den Herstellern.","questions":[{"id":"q1","promptDe":"Wie viel Plastikmüll gelangt jährlich in die Ozeane?","options":[{"id":"a","de":"Etwa 800.000 Tonnen"},{"id":"b","de":"Etwa 8 Millionen Tonnen"},{"id":"c","de":"Etwa 80 Millionen Tonnen"},{"id":"d","de":"Die Zahl ist unbekannt."}],"correct":"b","explanationAr":"الإجابة (B): النصّ يصرّح: \"acht Millionen Tonnen Plastikmüll\" سنوياً = 8 مليون طن. التعبير \"Müllwagen pro Minute\" يوضح الحجم الهائل."},{"id":"q2","promptDe":"Welche Folge für Meerestiere wird NICHT genannt?","options":[{"id":"a","de":"Sie verheddern sich in Netzen."},{"id":"b","de":"Sie verwechseln Plastik mit Nahrung."},{"id":"c","de":"Sie werden durch Giftstoffe geschädigt."},{"id":"d","de":"Sie können nicht mehr schwimmen."}],"correct":"d","explanationAr":"الإجابة (D): النصّ يذكر (A) verheddern sich، (B) verwechseln mit Nahrung، (C) Giftstoffe. لكن لا يذكر فقدان القدرة على السباحة."},{"id":"q3","promptDe":"Wo wurde Mikroplastik bereits nachgewiesen?","options":[{"id":"a","de":"Nur im Trinkwasser."},{"id":"b","de":"In Trinkwasser, Salz und menschlichem Blut."},{"id":"c","de":"Nur in Meeresfischen."},{"id":"d","de":"Ausschließlich in asiatischen Ländern."}],"correct":"b","explanationAr":"الإجابة (B): الفقرة الأولى: \"Mikroplastik wurde in Trinkwasser, Salz und sogar im menschlichen Blut nachgewiesen\". الخيار (A) ناقص، (C) و(D) مغلوطان."},{"id":"q4","promptDe":"Woher stammt der Großteil des Plastikmülls im Meer?","options":[{"id":"a","de":"Aus Industriestaaten."},{"id":"b","de":"Aus Ländern mit schlechter Abfallwirtschaft."},{"id":"c","de":"Von Kreuzfahrtschiffen."},{"id":"d","de":"Aus der Fischerei."}],"correct":"b","explanationAr":"الإجابة (B): \"stammt nicht aus den Industriestaaten, sondern aus Ländern, in denen die Abfallwirtschaft unzureichend entwickelt ist\". نظام إدارة النفايات الضعيف هو السبب."},{"id":"q5","promptDe":"Was fordern Umweltschutzorganisationen zusätzlich zum EU-Verbot?","options":[{"id":"a","de":"Höhere Steuern auf Plastik."},{"id":"b","de":"Reduzierung der Plastikproduktion selbst."},{"id":"c","de":"Mehr Werbung gegen Plastik."},{"id":"d","de":"Bessere Mülltrennung in Privathaushalten."}],"correct":"b","explanationAr":"الإجابة (B): \"fordern aber, dass auch die Produktion selbst reduziert werden müsse\". المشكلة الحقيقيّة تبدأ عند الشركات المُنتِجة لا عند المستهلك."}]},{"id":"lese-2","titleDe":"Elektroautos: Die Zukunft des Verkehrs?","textDe":"Die Zahl der in Deutschland zugelassenen Elektroautos ist in den vergangenen fünf Jahren explosionsartig gestiegen. Ob die batteriebetriebenen Fahrzeuge wirklich der Schlüssel zu einer klimafreundlichen Mobilität sind, ist unter Fachleuten jedoch umstritten.\n\nBefürworter weisen darauf hin, dass E-Autos im Betrieb keine Abgase ausstoßen und dadurch besonders in Städten die Luftqualität verbessern. Wird der Strom aus erneuerbaren Energien gewonnen, fällt auch die Klimabilanz deutlich günstiger aus als bei Benzin- oder Dieselfahrzeugen. Hinzu kommt, dass Elektromotoren weitaus leiser arbeiten, was den Lärm in Innenstädten mindert.\n\nKritiker hingegen verweisen auf die Produktion der Batterien: Sie verbraucht enorme Mengen an Rohstoffen wie Lithium, Kobalt und Nickel, die oft unter menschenrechtlich bedenklichen Bedingungen abgebaut werden. Zudem sei der Strom in Deutschland noch nicht vollständig CO₂-neutral. Ein weiteres Problem ist das dünne Ladenetz, besonders auf dem Land.\n\nDie Bundesregierung hat sich das Ziel gesetzt, bis 2030 mindestens 15 Millionen Elektroautos auf deutschen Straßen zu haben. Ob das zu schaffen ist, hängt nicht zuletzt davon ab, ob attraktive Kaufprämien und ein flächendeckender Ausbau der Ladeinfrastruktur gelingen.","questions":[{"id":"q6","promptDe":"Wie hat sich der Markt für E-Autos laut Text entwickelt?","options":[{"id":"a","de":"Er ist langsam gewachsen."},{"id":"b","de":"Er ist rasant gewachsen."},{"id":"c","de":"Er ist gesunken."},{"id":"d","de":"Er ist unverändert geblieben."}],"correct":"b","explanationAr":"الإجابة (B): \"explosionsartig gestiegen\" = ارتفع بشكل انفجاري/سريع جداً = rasant gewachsen. الكلمتان مترادفتان في الألمانيّة للتعبير عن نموّ سريع."},{"id":"q7","promptDe":"Welcher Umweltvorteil von E-Autos wird genannt?","options":[{"id":"a","de":"Sie sind schneller als Benziner."},{"id":"b","de":"Sie stoßen im Betrieb keine Abgase aus."},{"id":"c","de":"Sie sind günstiger im Kauf."},{"id":"d","de":"Sie können recycelt werden."}],"correct":"b","explanationAr":"الإجابة (B): \"E-Autos im Betrieb keine Abgase ausstoßen\" = لا تطلق غازات عادم أثناء الاستخدام. الخيارات الأخرى لا علاقة لها بالبيئة."},{"id":"q8","promptDe":"Was kritisieren Gegner an der Batterieproduktion?","options":[{"id":"a","de":"Sie dauert zu lange."},{"id":"b","de":"Rohstoffabbau unter problematischen Bedingungen."},{"id":"c","de":"Sie ist zu teuer."},{"id":"d","de":"Die Batterien sind zu klein."}],"correct":"b","explanationAr":"الإجابة (B): \"Rohstoffe wie Lithium, Kobalt und Nickel, die oft unter menschenrechtlich bedenklichen Bedingungen abgebaut werden\" — استخراج الليثيوم والكوبالت في ظروف مقلقة حقوق إنسان."},{"id":"q9","promptDe":"Welches Infrastrukturproblem wird genannt?","options":[{"id":"a","de":"Zu wenige Parkplätze."},{"id":"b","de":"Ein dünnes Ladenetz, besonders auf dem Land."},{"id":"c","de":"Zu enge Straßen."},{"id":"d","de":"Fehlende Autobahnen."}],"correct":"b","explanationAr":"الإجابة (B): \"das dünne Ladenetz, besonders auf dem Land\" — شبكة محطات الشحن ضعيفة خاصّةً في الأرياف."},{"id":"q10","promptDe":"Wie lautet das Ziel der Bundesregierung für 2030?","options":[{"id":"a","de":"5 Millionen E-Autos"},{"id":"b","de":"15 Millionen E-Autos"},{"id":"c","de":"50 Millionen E-Autos"},{"id":"d","de":"Alle Autos sollen elektrisch sein."}],"correct":"b","explanationAr":"الإجابة (B): النصّ ينصّ صراحةً على \"bis 2030 mindestens 15 Millionen Elektroautos\". رقم رسمي يمكن حفظه."}]}],"sprachbausteine":[{"id":"sb1","contextDe":"Die Umweltverschmutzung hat ___ den letzten Jahrzehnten stark zugenommen.","blank":"Präposition","options":[{"id":"a","de":"seit"},{"id":"b","de":"in"},{"id":"c","de":"für"},{"id":"d","de":"von"}],"correct":"b","explanationAr":"**in + Dativ** للدلالة على فترة زمنية كاملة انقضت (\"خلال\"). \"in den letzten Jahrzehnten\" = خلال العقود الأخيرة. (seit = منذ نقطة في الماضي؛ für = لفترة مستقبلية)."},{"id":"sb2","contextDe":"Je mehr CO₂ wir ausstoßen, ___ wärmer wird das Klima.","blank":"Konjunktion","options":[{"id":"a","de":"desto"},{"id":"b","de":"so"},{"id":"c","de":"dann"},{"id":"d","de":"als"}],"correct":"a","explanationAr":"**Je …, desto …** = كلّما … أكثر. بنية قارنة قياسية في الألمانية: \"Je + Komparativ, desto + Komparativ\". (أو Je …, umso … مرادف)."},{"id":"sb3","contextDe":"Wenn wir nichts unternehmen, ___ die Temperaturen weiter steigen.","blank":"Zukunft","options":[{"id":"a","de":"werden"},{"id":"b","de":"würden"},{"id":"c","de":"haben"},{"id":"d","de":"sind"}],"correct":"a","explanationAr":"**Futur I (werden + Infinitiv)** للدلالة على مستقبل واقعي/محتمل بعد شرط حقيقي. (würden تُستخدم مع شرط افتراضي Konjunktiv II)."},{"id":"sb4","contextDe":"Es ist wichtig, ___ wir alle unseren Beitrag zum Klimaschutz leisten.","blank":"Konjunktion","options":[{"id":"a","de":"ob"},{"id":"b","de":"dass"},{"id":"c","de":"wenn"},{"id":"d","de":"damit"}],"correct":"b","explanationAr":"**dass** بعد \"Es ist wichtig\" = أن + فعل. (ob = سؤال غير مباشر \"هل\"؛ wenn = \"إذا/عندما\"؛ damit = \"لكي\" غرض)."},{"id":"sb5","contextDe":"Der Bericht wurde gestern ___ dem Minister vorgestellt.","blank":"Passiv","options":[{"id":"a","de":"durch"},{"id":"b","de":"von"},{"id":"c","de":"mit"},{"id":"d","de":"bei"}],"correct":"b","explanationAr":"**von + Dativ** في المبني للمجهول للدلالة على الفاعل (العامل الأصلي). \"Der Bericht wurde vom Minister vorgestellt\" = قُدِّم التقرير من قِبَل الوزير. (durch تستخدم لأداة/وسيلة)."},{"id":"sb6","contextDe":"Die Klimakonferenz fand ___ großem öffentlichen Interesse statt.","blank":"Präposition","options":[{"id":"a","de":"mit"},{"id":"b","de":"unter"},{"id":"c","de":"bei"},{"id":"d","de":"vor"}],"correct":"b","explanationAr":"**unter + Dativ** للدلالة على ظرف/شرط عام (\"تحت / وسط\"). \"unter großem Interesse\" = وسط اهتمام كبير. تعبير ثابت مع Interesse/Aufsicht/Druck."}],"schreiben":{"id":"schreiben-2","topicAr":"كتابة خطاب للصحيفة حول السياسة البيئية","topicDe":"Leserbrief: Sollten Kurzstreckenflüge verboten werden?","contextDe":"Sie haben in einer Zeitung gelesen, dass die Regierung überlegt, Inlandsflüge unter 500 km zu verbieten. Schreiben Sie einen Leserbrief (150–200 Wörter), in dem Sie:","bulletPoints":["Ihre Meinung klar äußern.","Zwei Argumente nennen (pro oder contra).","Ein konkretes Beispiel geben.","Einen alternativen Vorschlag machen."],"redemittel":["Mit großem Interesse habe ich Ihren Artikel gelesen.","Ich teile die Auffassung des Autors / Ich bin anderer Meinung.","Ein zentrales Argument ist für mich, dass …","Zum einen …, zum anderen …","Als Alternative schlage ich vor, …","Abschließend möchte ich betonen, dass …"],"sampleEssayDe":"Sehr geehrte Redaktion,\n\nmit großem Interesse habe ich Ihren Artikel über das geplante Verbot von Kurzstreckenflügen gelesen. Ich bin der Ansicht, dass ein solches Verbot grundsätzlich sinnvoll wäre, allerdings mit einigen Einschränkungen.\n\nZum einen verursachen Kurzstreckenflüge pro Kilometer deutlich mehr CO₂ als Langstreckenflüge, da Start und Landung besonders energieintensiv sind. Zum anderen existiert in Deutschland ein gut ausgebautes Schienennetz, sodass die Bahn eine echte Alternative darstellt. So braucht der ICE von Berlin nach Hamburg nur etwa 100 Minuten — genauso lange wie ein Flug, wenn man An- und Abreise zum Flughafen einrechnet.\n\nAllerdings darf man nicht vergessen, dass die Bahnpreise in Deutschland häufig teurer sind als die von Billigfliegern. Daher wäre ein reines Verbot nur dann gerecht, wenn gleichzeitig die Ticketpreise der Bahn gesenkt werden.\n\nAls Alternative schlage ich vor, Kurzstreckenflüge bis 500 km schrittweise zu verteuern und parallel die Bahn attraktiver zu machen. So würden die Menschen selbst entscheiden, aber in die richtige Richtung gelenkt.\n\nMit freundlichen Grüßen\n(193 Wörter)","sampleEssayAr":"السّادة المحترمون في هيئة التحرير،\n\n**بكلّ اهتمام** قرأت مقالتكم حول منع الرحلات الجوّية القصيرة المُخطَّط له. **برأيي** يبدو هذا المنع منطقياً مبدئياً لكن مع بعض التحفّظات.\n\n**من جهة**، تنتج الرحلات القصيرة كمّية CO₂ أكبر لكلّ كيلومتر من الرحلات الطويلة لأنّ الإقلاع والهبوط يستهلكان طاقة هائلة. **من جهة أخرى**، يوجد في ألمانيا شبكة قطارات متطوّرة تشكّل بديلاً حقيقياً. فمثلاً يستغرق الـICE من برلين إلى هامبورغ 100 دقيقة فقط — نفس وقت الرحلة الجوّية لو حسبنا وقت الوصول للمطار والمغادرة منه.\n\n**مع ذلك، لا يجب أن ننسى** أنّ أسعار القطار في ألمانيا غالباً أعلى من أسعار شركات الطيران الاقتصادية. لذا سيكون المنع عادلاً فقط عند خفض أسعار القطار معاً.\n\n**كبديل أقترح** رفع أسعار الرحلات القصيرة تدريجياً وجعل القطار أكثر جاذبية بالتوازي. هكذا يقرّر الناس بأنفسهم لكن في الاتّجاه الصحيح.\n\nمع أطيب التحيّات"},"sprechen":[{"id":"sp1","partAr":"الجزء 1 — تقديم الذات مع موقف بيئي","partDe":"Teil 1 — Sich vorstellen und Umweltverhalten","topicAr":"قدّم نفسك وتحدّث عن عاداتك البيئية اليومية.","topicDe":"Stellen Sie sich kurz vor und sprechen Sie darüber, was Sie persönlich für die Umwelt tun.","redemittel":["Ich heiße … und interessiere mich seit Langem für Umweltthemen.","In meinem Alltag versuche ich, …","Was mir besonders wichtig ist, ist …","Zu Hause achte ich darauf, dass …","Ich verzichte bewusst auf …"],"sampleAnswerDe":"Mein Name ist Lina Hammoud, ich bin 28 Jahre alt und lebe seit sechs Jahren in München, wo ich als Architektin arbeite. Umweltschutz ist mir besonders wichtig, denn ich denke, jeder Einzelne kann etwas beitragen.\n\nIn meinem Alltag versuche ich, möglichst wenig zu konsumieren: Ich kaufe Second-Hand-Kleidung, benutze eine wiederverwendbare Trinkflasche und fahre mit dem Fahrrad zur Arbeit, auch wenn es regnet. Auf Flüge verzichte ich fast komplett — wenn ich meine Familie in Syrien nicht besuchen muss, fahre ich lieber mit der Bahn.\n\nZu Hause achten mein Partner und ich darauf, dass wir wenig Lebensmittel wegwerfen. Wir planen unsere Einkäufe und kochen aus Resten. Es ist zwar nicht immer einfach, aber am Ende spart man dadurch auch Geld."},{"id":"sp2","partAr":"الجزء 2 — وصف صورة (مظاهرة بيئية/مصنع/سدّ ...)","partDe":"Teil 2 — Bildbeschreibung: Klimademo oder Windpark","topicAr":"صف صورة لمظاهرة مناخية أو مزرعة رياح وأبدِ رأيك فيها.","topicDe":"Beschreiben Sie ein Bild zum Thema Umwelt und äußern Sie Ihre Meinung.","redemittel":["Das Foto zeigt offensichtlich …","Im Zentrum / am Rand sehe ich …","Auffällig ist vor allem …","Die Atmosphäre wirkt … (engagiert, ernst, hoffnungsvoll)","Das erinnert mich an …","Persönlich halte ich das Thema für …"],"sampleAnswerDe":"Das Foto zeigt offensichtlich eine Demonstration, vermutlich eine \"Fridays for Future\"-Aktion. Im Zentrum sieht man mehrere Jugendliche, die Plakate in die Höhe halten. Auf einem steht \"There is no Planet B\", auf einem anderen \"Rettet die Bäume!\".\n\nAuffällig ist vor allem, wie viele junge Menschen — wahrscheinlich Schülerinnen und Schüler — teilnehmen. Die Atmosphäre wirkt engagiert und laut, aber zugleich friedlich. Im Hintergrund erkennt man ein Rathausgebäude und einige Polizisten, die die Veranstaltung begleiten.\n\nPersönlich halte ich solche Demonstrationen für sehr wichtig. Sie zeigen, dass sich die junge Generation Sorgen um die Zukunft macht und Politiker unter Druck setzt. Gleichzeitig reichen Proteste allein nicht — am Ende braucht es konkrete Gesetze und Investitionen."},{"id":"sp3","partAr":"الجزء 3 — نقاش: كيف نخفّض استهلاك الطاقة في الشركة؟","partDe":"Teil 3 — Diskussion: Energiesparen im Unternehmen","topicAr":"تناقش مع شريكك حول كيفيّة تخفيض استهلاك الطاقة في شركتكما.","topicDe":"Ihre Firma will Energie sparen. Diskutieren Sie mit Ihrem Partner über: Heizung, Beleuchtung, Homeoffice, Dienstreisen. Einigen Sie sich auf drei Maßnahmen.","redemittel":["Ich würde vorschlagen, dass wir …","Wäre es nicht sinnvoll, …?","Da stimme ich Ihnen vollkommen zu.","Ich sehe das etwas anders, weil …","Können wir uns darauf einigen, dass …?","Als dritte Maßnahme schlage ich vor, …"],"sampleAnswerDe":"A: Ich würde vorschlagen, dass wir die Heizung in allen Büros um zwei Grad senken. Das spart viel Strom und Geld.\n\nB: Da stimme ich Ihnen vollkommen zu. Eine zweite Idee wäre, in allen Räumen LED-Lampen einzubauen, falls das noch nicht geschehen ist.\n\nA: Sehr gut. Wäre es nicht auch sinnvoll, Dienstreisen innerhalb Deutschlands nur noch mit der Bahn statt mit dem Flugzeug zu machen?\n\nB: Grundsätzlich ja, allerdings dauert die Bahn manchmal länger. Vielleicht könnten wir es als Regel einführen, aber Ausnahmen erlauben, wenn eine Reise extrem dringend ist.\n\nA: Einverstanden. Können wir uns darauf einigen, dass wir die drei Maßnahmen — Heizung senken, LED-Umstellung und Bahn statt Flug — der Geschäftsleitung vorschlagen?\n\nB: Ja, das ist ein guter Plan. Ich schreibe die Zusammenfassung und schicke sie Ihnen morgen."}]},{"id":"telc-b2-3","titleAr":"نموذج 3 — الصحّة ونمط الحياة","titleDe":"Modelltest 3 — Gesundheit & Lebensstil","level":"B2","durationMin":165,"readingPassages":[{"id":"lese-1","titleDe":"Schlaf — der unterschätzte Gesundheitsfaktor","textDe":"Rund ein Drittel unseres Lebens verbringen wir schlafend — doch nur wenige Menschen achten tatsächlich auf die Qualität ihres Schlafs. Dabei zeigen zahlreiche Studien, dass guter Schlaf genauso wichtig für die Gesundheit ist wie ausgewogene Ernährung und regelmäßige Bewegung.\n\nErwachsene benötigen im Durchschnitt sieben bis neun Stunden Schlaf pro Nacht. Wer dauerhaft weniger schläft, riskiert ernsthafte gesundheitliche Folgen: Das Immunsystem wird geschwächt, die Konzentration lässt nach, und das Risiko für Herz-Kreislauf-Erkrankungen sowie Diabetes steigt deutlich. Auch die psychische Gesundheit leidet — Schlafmangel gilt als einer der Hauptauslöser von Depressionen und Angststörungen.\n\nBesonders problematisch ist die zunehmende Nutzung von Smartphones und Tablets kurz vor dem Einschlafen. Das blaue Licht der Bildschirme unterdrückt die Ausschüttung von Melatonin, dem körpereigenen Schlafhormon. Die Folge: Wir schlafen später ein und schlechter durch. Experten empfehlen daher, mindestens eine Stunde vor dem Zubettgehen auf Bildschirme zu verzichten.\n\nWer regelmäßig Einschlafprobleme hat, sollte nicht sofort zu Schlafmitteln greifen. Oft helfen einfache Rituale wie feste Schlafenszeiten, ein kühles und dunkles Schlafzimmer oder eine kurze Entspannungsübung. Erst wenn diese Maßnahmen dauerhaft nicht wirken, ist ärztliche Beratung sinnvoll.","questions":[{"id":"q1","promptDe":"Wie viele Stunden Schlaf benötigen Erwachsene laut Text?","options":[{"id":"a","de":"5 bis 6 Stunden"},{"id":"b","de":"7 bis 9 Stunden"},{"id":"c","de":"10 bis 12 Stunden"},{"id":"d","de":"Der Text macht keine Angabe."}],"correct":"b","explanationAr":"الإجابة (B): النصّ: \"sieben bis neun Stunden Schlaf pro Nacht\". هذا معيار طبّي عالمي للبالغين."},{"id":"q2","promptDe":"Welche Folge von Schlafmangel wird NICHT genannt?","options":[{"id":"a","de":"Schwächeres Immunsystem"},{"id":"b","de":"Höheres Diabetes-Risiko"},{"id":"c","de":"Bessere Kreativität"},{"id":"d","de":"Depressionen"}],"correct":"c","explanationAr":"الإجابة (C): النصّ يذكر ضعف المناعة، الكوليسترول، السكّري، والاكتئاب كنتائج سلبيّة. لم يذكر أيّ فائدة إيجابية للإبداع."},{"id":"q3","promptDe":"Warum sind Smartphones vor dem Schlafengehen problematisch?","options":[{"id":"a","de":"Sie strahlen Wärme ab."},{"id":"b","de":"Das blaue Licht hemmt Melatonin."},{"id":"c","de":"Sie machen Lärm."},{"id":"d","de":"Sie sind zu schwer zu halten."}],"correct":"b","explanationAr":"الإجابة (B): \"Das blaue Licht der Bildschirme unterdrückt die Ausschüttung von Melatonin\". Melatonin = هرمون النوم؛ الضوء الأزرق يعيق إفرازه."},{"id":"q4","promptDe":"Wie lange vor dem Schlafen sollte man auf Bildschirme verzichten?","options":[{"id":"a","de":"Mindestens 15 Minuten"},{"id":"b","de":"Mindestens eine Stunde"},{"id":"c","de":"Mindestens drei Stunden"},{"id":"d","de":"Man soll gar keine Bildschirme benutzen."}],"correct":"b","explanationAr":"الإجابة (B): \"mindestens eine Stunde vor dem Zubettgehen\". ساعة كاملة على الأقلّ للسماح للميلاتونين بالتراكم."},{"id":"q5","promptDe":"Was empfiehlt der Text bei Einschlafproblemen?","options":[{"id":"a","de":"Sofort Schlafmittel einzunehmen."},{"id":"b","de":"Feste Rituale und ggf. ärztliche Beratung."},{"id":"c","de":"Einen Kaffee zu trinken."},{"id":"d","de":"Länger fernzusehen."}],"correct":"b","explanationAr":"الإجابة (B): النصّ يوصي بالعادات البسيطة (أوقات ثابتة، غرفة باردة ومظلمة، تمارين استرخاء) أوّلاً، وعند الحاجة استشارة طبيب. لا ينصح بالأدوية مباشرةً."}]},{"id":"lese-2","titleDe":"Vegetarische Ernährung: Trend oder Verantwortung?","textDe":"In Deutschland ernähren sich inzwischen rund zehn Prozent der Bevölkerung vegetarisch, etwa zwei Prozent sogar vegan. Tendenz: steigend. Besonders junge Menschen zwischen 18 und 30 verzichten zunehmend auf Fleisch — aus ethischen, gesundheitlichen oder ökologischen Gründen.\n\nErnährungswissenschaftler bestätigen, dass eine pflanzenbasierte Ernährung bei guter Planung alle notwendigen Nährstoffe liefern kann. Vorteile gibt es viele: weniger gesättigte Fette, mehr Ballaststoffe, Vitamine und sekundäre Pflanzenstoffe. Studien zeigen, dass Vegetarier seltener an Herz-Kreislauf-Erkrankungen, Diabetes Typ 2 und bestimmten Krebsarten leiden.\n\nDoch nicht alle Experten sind uneingeschränkt begeistert. Besonders bei veganer Ernährung besteht die Gefahr, dass Nährstoffe wie Vitamin B12, Eisen, Kalzium oder Omega-3-Fettsäuren zu kurz kommen. Gerade schwangere Frauen, Kinder und ältere Menschen sollten daher besonders auf eine ausgewogene Lebensmittelauswahl achten oder gegebenenfalls Nahrungsergänzungsmittel einnehmen.\n\nEin weiterer Aspekt ist die Umwelt: Die Fleischproduktion verursacht etwa 14,5 Prozent aller weltweiten Treibhausgasemissionen. Wer also auf Fleisch verzichtet oder seinen Konsum deutlich reduziert, leistet nicht nur einen Beitrag zur eigenen Gesundheit, sondern auch zum Klimaschutz.","questions":[{"id":"q6","promptDe":"Welche Altersgruppe ernährt sich besonders oft vegetarisch?","options":[{"id":"a","de":"Kinder unter 10 Jahren"},{"id":"b","de":"18- bis 30-Jährige"},{"id":"c","de":"50- bis 65-Jährige"},{"id":"d","de":"Menschen über 70"}],"correct":"b","explanationAr":"الإجابة (B): \"Besonders junge Menschen zwischen 18 und 30 verzichten zunehmend auf Fleisch\". الشباب هم الفئة الأكثر اعتماداً للنظام النباتي."},{"id":"q7","promptDe":"Welcher gesundheitliche Vorteil wird genannt?","options":[{"id":"a","de":"Bessere Sicht"},{"id":"b","de":"Seltenere Herz-Kreislauf-Erkrankungen"},{"id":"c","de":"Größere Muskeln"},{"id":"d","de":"Helleres Haar"}],"correct":"b","explanationAr":"الإجابة (B): \"Vegetarier seltener an Herz-Kreislauf-Erkrankungen, Diabetes Typ 2 und bestimmten Krebsarten leiden\". 3 أمراض أقلّ انتشاراً عند النباتيين."},{"id":"q8","promptDe":"Welches Nährstoffrisiko wird bei Veganern genannt?","options":[{"id":"a","de":"Zu viel Eiweiß"},{"id":"b","de":"Mangel an Vitamin B12 und Eisen"},{"id":"c","de":"Zu viel Zucker"},{"id":"d","de":"Zu viele gesättigte Fette"}],"correct":"b","explanationAr":"الإجابة (B): \"Vitamin B12, Eisen, Kalzium oder Omega-3-Fettsäuren zu kurz kommen\". نقصان B12 شائع جداً عند النباتيين البحتين (فيتامين يوجد فقط في المنتجات الحيوانية)."},{"id":"q9","promptDe":"Welche Personengruppen sollten besonders aufpassen?","options":[{"id":"a","de":"Junge Männer"},{"id":"b","de":"Schwangere, Kinder und ältere Menschen"},{"id":"c","de":"Sportler"},{"id":"d","de":"Studenten"}],"correct":"b","explanationAr":"الإجابة (B): \"schwangere Frauen, Kinder und ältere Menschen sollten daher besonders auf eine ausgewogene Lebensmittelauswahl achten\". 3 فئات ذكرت حرفياً."},{"id":"q10","promptDe":"Wie viel der globalen Treibhausgase verursacht die Fleischproduktion?","options":[{"id":"a","de":"Etwa 1,5 %"},{"id":"b","de":"Etwa 14,5 %"},{"id":"c","de":"Etwa 45 %"},{"id":"d","de":"Etwa 80 %"}],"correct":"b","explanationAr":"الإجابة (B): النصّ: \"etwa 14,5 Prozent aller weltweiten Treibhausgasemissionen\". رقم رسمي من FAO يُستشهَد به كثيراً."}]}],"sprachbausteine":[{"id":"sb1","contextDe":"Obwohl er krank war, ___ er zur Arbeit gegangen.","blank":"Perfekt","options":[{"id":"a","de":"hat"},{"id":"b","de":"ist"},{"id":"c","de":"wird"},{"id":"d","de":"war"}],"correct":"b","explanationAr":"**gehen** فعل حركة → Perfekt مع **sein**: \"ist gegangen\". أفعال الحركة (gehen, fahren, kommen, laufen…) دائماً مع sein."},{"id":"sb2","contextDe":"Der Arzt hat ___ empfohlen, mehr Sport zu treiben.","blank":"Dativ","options":[{"id":"a","de":"mich"},{"id":"b","de":"mir"},{"id":"c","de":"mein"},{"id":"d","de":"meiner"}],"correct":"b","explanationAr":"**empfehlen + Dativ (الشخص) + Akkusativ (الشيء)**. \"Er hat **mir** (Dativ) es (Akk) empfohlen\". \"empfehlen\" دائماً مع Dativ للشخص."},{"id":"sb3","contextDe":"Immer mehr Menschen interessieren sich ___ gesunde Ernährung.","blank":"Präposition","options":[{"id":"a","de":"an"},{"id":"b","de":"auf"},{"id":"c","de":"für"},{"id":"d","de":"über"}],"correct":"c","explanationAr":"**sich interessieren für + Akkusativ** = يهتمّ بـ. حرف جرّ ثابت مع الفعل \"interessieren\". (احفظه: für!)."},{"id":"sb4","contextDe":"Die Anzahl der Raucher ist in den letzten Jahren deutlich ___.","blank":"Partizip II","options":[{"id":"a","de":"gesinkt"},{"id":"b","de":"gesunken"},{"id":"c","de":"gesunkt"},{"id":"d","de":"sinken"}],"correct":"b","explanationAr":"**sinken** فعل قويّ غير منتظم: sinken – sank – **gesunken**. تصريف شاذّ يجب حفظه (مثل finden–gefunden، trinken–getrunken)."},{"id":"sb5","contextDe":"Er isst so viel Gemüse, ___ er schnell satt wird.","blank":"Konjunktion","options":[{"id":"a","de":"dass"},{"id":"b","de":"als"},{"id":"c","de":"wie"},{"id":"d","de":"ob"}],"correct":"a","explanationAr":"**so …, dass …** = \"هكذا … بحيث …\" للدلالة على النتيجة/الأثر. البنية معتمدة: so + صفة/ظرف + dass + جملة فرعية."},{"id":"sb6","contextDe":"Die Weltgesundheitsorganisation rät ___ einem Konsum von weniger als 5 g Salz pro Tag.","blank":"Präposition","options":[{"id":"a","de":"auf"},{"id":"b","de":"zu"},{"id":"c","de":"für"},{"id":"d","de":"an"}],"correct":"b","explanationAr":"**raten zu + Dativ** = ينصح بـ. حرف جرّ ثابت مع الفعل \"raten\". (قارن: empfehlen بدون حرف جرّ!)."}],"schreiben":{"id":"schreiben-3","topicAr":"كتابة بريد إلكتروني لصديق حول صحّته","topicDe":"E-Mail: Ratschläge für einen gestressten Freund","contextDe":"Ihr deutscher Freund Lukas hat Ihnen geschrieben, dass er seit Monaten unter Stress, Schlafproblemen und Kopfschmerzen leidet. Schreiben Sie ihm eine E-Mail (150–200 Wörter), in der Sie:","bulletPoints":["Ihr Mitgefühl ausdrücken.","Über eine ähnliche eigene Erfahrung berichten.","Drei konkrete Ratschläge geben.","Ein gemeinsames Treffen vorschlagen."],"redemittel":["Lieber Lukas, es tut mir sehr leid zu hören, dass …","Ich kann dich gut verstehen, denn …","An deiner Stelle würde ich …","Hast du schon einmal überlegt, …?","Ein Tipp, der mir damals geholfen hat: …","Wir könnten uns doch am Wochenende … treffen."],"sampleEssayDe":"Lieber Lukas,\n\nes tut mir sehr leid zu hören, dass du so schlecht schläfst und ständig unter Kopfschmerzen leidest. Das klingt wirklich anstrengend, und ich kann dich gut verstehen. Vor zwei Jahren hatte ich genau dieselben Probleme, als ich gleichzeitig studierte und in Vollzeit arbeitete.\n\nAn deiner Stelle würde ich zuerst meine Smartphone-Nutzung abends reduzieren. Das klingt banal, aber mir hat es wirklich geholfen, ab 21 Uhr kein Handy mehr in der Hand zu haben.\n\nAußerdem empfehle ich dir, regelmäßig Sport zu machen, auch wenn es nur ein halbstündiger Spaziergang nach der Arbeit ist. Die frische Luft und die Bewegung senken das Stresslevel deutlich.\n\nMein dritter Tipp: Geh zum Hausarzt! Länger als zwei Monate solltest du mit Kopfschmerzen nicht herumlaufen, ohne die Ursache klären zu lassen.\n\nWir könnten uns doch am Samstag bei dir treffen — ich bringe etwas Gesundes zu essen mit und wir reden in Ruhe. Meld dich, wenn es passt.\n\nAlles Gute und bis bald,\ndein Khaled\n(185 Wörter)","sampleEssayAr":"عزيزي لوكاس،\n\n**يؤسفني جداً** أن أسمع أنّك تنام بشكل سيّء وتعاني من الصداع باستمرار. يبدو هذا مُرهِقاً حقّاً، **وأفهمك جيّداً**. قبل سنتين عانيت من نفس المشاكل تماماً، عندما كنت أدرس وأعمل بدوام كامل في نفس الوقت.\n\n**في مكانك سأقلّل** أوّلاً من استخدام الهاتف مساءً. يبدو الأمر بسيطاً لكنّه ساعدني فعلاً ألّا ألمس الهاتف بعد الساعة التاسعة.\n\nإضافةً إلى ذلك، **أنصحك** بممارسة الرياضة بانتظام، حتّى لو كانت مجرّد مشي نصف ساعة بعد العمل. الهواء الطلق والحركة يخفّضان مستوى التوتّر بشكل واضح.\n\n**نصيحتي الثالثة**: اذهب لطبيب الأسرة! لا يجب أن تتجاهل الصداع لأكثر من شهرين دون توضيح السبب.\n\n**يمكننا أن نلتقي** يوم السبت عندك — سأحضر طعاماً صحّياً ونتحدّث بهدوء. كَلِّمْنِي إذا كان الوقت مناسباً.\n\nتحيّاتي وأتمنّى لك الخير،\nصديقك خالد"},"sprechen":[{"id":"sp1","partAr":"الجزء 1 — تقديم الذات مع عادات صحّية","partDe":"Teil 1 — Sich vorstellen und über Gesundheit sprechen","topicAr":"قدّم نفسك وتحدّث عن عاداتك الصحّية.","topicDe":"Stellen Sie sich vor und sprechen Sie darüber, was Sie für Ihre Gesundheit tun.","redemittel":["Mein Name ist … und ich achte sehr auf meine Gesundheit.","Was mir besonders wichtig ist, ist …","Ich treibe regelmäßig Sport, zum Beispiel …","Bei der Ernährung achte ich darauf, dass …","Gegen Stress hilft mir vor allem …"],"sampleAnswerDe":"Mein Name ist Yara Al-Khatib, ich bin 35 Jahre alt und arbeite als Apothekerin in Köln. Da ich beruflich täglich mit Patienten zu tun habe, ist mir eine gesunde Lebensweise besonders wichtig.\n\nWas meinen Sport betrifft: Ich gehe dreimal pro Woche schwimmen, weil das rückenfreundlich ist, und mache zusätzlich einmal pro Woche Yoga. Am Wochenende fahre ich gern mit dem Fahrrad ins Grüne.\n\nBei der Ernährung achte ich darauf, möglichst viel Gemüse und Obst zu essen. Fleisch esse ich nur ein- bis zweimal pro Woche, dafür viel Fisch. Ich koche fast alles selbst, weil Fertiggerichte meistens zu viel Salz und Zucker enthalten.\n\nGegen Stress hilft mir vor allem frische Luft. Nach einem langen Arbeitstag mache ich immer noch einen kurzen Spaziergang, bevor ich nach Hause komme. Das klingt wenig, aber es macht einen großen Unterschied."},{"id":"sp2","partAr":"الجزء 2 — وصف صورة (مستشفى/صالة رياضة/سوق خضار)","partDe":"Teil 2 — Bildbeschreibung: Fitnessstudio oder Wochenmarkt","topicAr":"صف صورة لصالة رياضة أو سوق خضار وأبدِ رأيك.","topicDe":"Beschreiben Sie ein Bild zum Thema Gesundheit und äußern Sie Ihre Meinung.","redemittel":["Auf dem Bild erkennt man …","Die Szene spielt sich offenbar … ab.","Im Vordergrund steht … / sitzt …","Was mir besonders auffällt, ist …","Vermutlich handelt es sich um …","Persönlich finde ich solche Orte …"],"sampleAnswerDe":"Auf dem Bild erkennt man einen klassischen Wochenmarkt in einer deutschen Innenstadt. Die Szene spielt sich offenbar an einem sonnigen Samstagmorgen ab, denn viele Menschen tragen leichte Jacken und halten Einkaufstaschen in der Hand.\n\nIm Vordergrund steht ein Obst- und Gemüsestand mit einer beeindruckenden Auswahl: rote Tomaten, grüne Salate, verschiedene Apfelsorten und frische Kräuter. Die Preise sind auf kleinen Kreidetafeln angeschrieben. Ein älterer Verkäufer lächelt eine Kundin an und reicht ihr eine Tüte.\n\nWas mir besonders auffällt, ist die familiäre Atmosphäre. Die Kunden unterhalten sich mit den Verkäufern, Kinder probieren Obststücke, und im Hintergrund spielt sogar ein Straßenmusiker.\n\nPersönlich finde ich solche Wochenmärkte großartig, weil sie nicht nur gesunde, regionale Produkte anbieten, sondern auch das soziale Leben in den Städten bereichern."},{"id":"sp3","partAr":"الجزء 3 — نقاش: كيف نجعل المدرسة أكثر صحّية؟","partDe":"Teil 3 — Diskussion: Gesündere Schulen","topicAr":"تناقش مع شريكك كيف يمكن جعل المدارس أكثر صحّيةً (طعام، رياضة، فترات استراحة).","topicDe":"Diskutieren Sie: Wie kann man Schulen in Deutschland gesünder machen? Denken Sie an Essen, Sport, Pausen, Unterrichtszeiten. Einigen Sie sich auf drei konkrete Maßnahmen.","redemittel":["Ich sehe das Problem vor allem bei …","Ein erster wichtiger Schritt wäre, …","Was ich auch wichtig finde, ist …","Das sehe ich ähnlich, aber wir sollten zusätzlich …","Könnten wir uns darauf verständigen, dass …?","Drittens könnten wir vorschlagen, …"],"sampleAnswerDe":"A: Ich sehe das Problem vor allem beim Essen in der Kantine. Es gibt zu viel Fastfood und zu wenig frisches Gemüse.\n\nB: Das sehe ich ähnlich, aber wir sollten zusätzlich über den Sportunterricht sprechen. Zweimal pro Woche 45 Minuten sind einfach zu wenig.\n\nA: Ein erster wichtiger Schritt wäre also, die Kantine umzustellen — regionales, saisonales Essen und weniger zuckerhaltige Getränke.\n\nB: Einverstanden. Ein zweiter Punkt wäre, täglich mindestens eine Bewegungspause einzubauen, nicht nur im Sportunterricht.\n\nA: Und drittens könnten wir vorschlagen, den Unterricht erst um neun Uhr beginnen zu lassen. Studien zeigen, dass Schülerinnen und Schüler dann besser lernen.\n\nB: Das klingt logisch, auch wenn es organisatorisch schwierig wäre. Könnten wir uns darauf verständigen, dass wir diese drei Maßnahmen — gesunde Kantine, Bewegungspausen und späterer Unterrichtsbeginn — der Schulleitung empfehlen?\n\nA: Perfekt, damit bin ich einverstanden."}]},{"id":"telc-b2-4","titleAr":"نموذج 4 — التعليم والمدرسة","titleDe":"Modelltest 4 — Bildung & Schule","level":"B2","durationMin":165,"readingPassages":[{"id":"lese-1","titleDe":"Schule der Zukunft: Tablet statt Tafel?","textDe":"Immer mehr Schulen in Deutschland setzen auf digitale Geräte im Unterricht. Tablets und Laptops ersetzen zunehmend Hefte und Schulbücher. Befürworter argumentieren, dass digitale Medien die Schüler besser auf den Arbeitsmarkt vorbereiten und individuelles Lernen erleichtern. Lernspiele, interaktive Übungen und sofortiges Feedback würden den Unterricht abwechslungsreicher gestalten.\n\nKritiker hingegen warnen vor den Risiken: Konzentrationsprobleme, Schlafstörungen durch Bildschirmzeit und der Verlust grundlegender Fähigkeiten wie das Schreiben mit der Hand stehen im Zentrum der Diskussion. Eine Studie der OECD aus dem Jahr 2023 zeigt zudem, dass Schüler, die täglich mehrere Stunden am Bildschirm lernen, in Tests zum Leseverständnis schlechter abschneiden als ihre Mitschüler mit traditionellen Lernmethoden.\n\nBildungsexperten plädieren daher für einen Mittelweg: Digitale Geräte sollten gezielt und maßvoll eingesetzt werden, ergänzend zu klassischen Methoden — nicht als Ersatz. Entscheidend sei vor allem die Qualifikation der Lehrkräfte. Ohne ausreichende Schulung bleibe das Potenzial der neuen Technik ungenutzt.","questions":[{"id":"q1","promptDe":"Was ist das Hauptargument der Befürworter digitaler Medien?","options":[{"id":"a","de":"Sie sind billiger als Bücher."},{"id":"b","de":"Sie bereiten besser auf den Arbeitsmarkt vor."},{"id":"c","de":"Sie sind umweltfreundlicher."},{"id":"d","de":"Sie machen Lehrer überflüssig."}],"correct":"b","explanationAr":"الإجابة (B): النصّ يقول صراحةً أنّ المؤيّدين يرون أنّ الأجهزة الرقميّة \"Schüler besser auf den Arbeitsmarkt vorbereiten\". الخيارات الأخرى ليست مذكورة."},{"id":"q2","promptDe":"Welches Risiko nennt der Text?","options":[{"id":"a","de":"Höhere Schulgebühren."},{"id":"b","de":"Verlust grundlegender Fähigkeiten wie Handschrift."},{"id":"c","de":"Mehr Hausaufgaben."},{"id":"d","de":"Internetausfälle."}],"correct":"b","explanationAr":"الإجابة (B): \"der Verlust grundlegender Fähigkeiten wie das Schreiben mit der Hand\" مذكور بوضوح. الكتابة باليد مهارة معرفيّة تطوّر الذاكرة."},{"id":"q3","promptDe":"Was zeigt die OECD-Studie von 2023?","options":[{"id":"a","de":"Schüler mit Tablets sind motivierter."},{"id":"b","de":"Bildschirmlernen verbessert das Leseverständnis."},{"id":"c","de":"Lange Bildschirmzeit verschlechtert das Leseverständnis."},{"id":"d","de":"Tablets sparen Geld."}],"correct":"c","explanationAr":"الإجابة (C): النصّ يقول إنّ الطلّاب الذين يدرسون عدّة ساعات يومياً على الشاشة \"schlechter abschneiden\" في اختبارات الفهم القرائي."},{"id":"q4","promptDe":"Was empfehlen Bildungsexperten?","options":[{"id":"a","de":"Vollständige Digitalisierung."},{"id":"b","de":"Verbot aller digitalen Geräte."},{"id":"c","de":"Einen ausgewogenen Mittelweg."},{"id":"d","de":"Online-Unterricht von zu Hause."}],"correct":"c","explanationAr":"الإجابة (C): \"Bildungsexperten plädieren für einen Mittelweg\" — وسط متوازن بين الرقمي والكلاسيكي. هذا الموقف الحكيم."},{"id":"q5","promptDe":"Worauf kommt es laut Experten besonders an?","options":[{"id":"a","de":"Auf die Marke des Tablets."},{"id":"b","de":"Auf die Schulung der Lehrkräfte."},{"id":"c","de":"Auf die Größe der Klasse."},{"id":"d","de":"Auf das Alter der Schüler."}],"correct":"b","explanationAr":"الإجابة (B): \"Entscheidend sei vor allem die Qualifikation der Lehrkräfte\" — تأهيل المعلّمين هو المحور. بدونه، التكنولوجيا تبقى بلا فائدة."}]}],"sprachbausteine":[{"id":"sb1","contextDe":"Je mehr Schüler digitale Geräte nutzen, ___ wichtiger wird die Medienkompetenz.","blank":"Konjunktion","options":[{"id":"a","de":"desto"},{"id":"b","de":"als"},{"id":"c","de":"wie"},{"id":"d","de":"so"}],"correct":"a","explanationAr":"**je … desto** = \"كلّما … أكثر\" — بنية مقارنة ثابتة. كلّما زاد X، زاد Y بالتناسب. (als = من بعد المقارنة، wie = مثل، so = هكذا)."},{"id":"sb2","contextDe":"Die Lehrkraft, ___ Methoden modern sind, hat den Preis gewonnen.","blank":"Genitiv-Relativpronomen","options":[{"id":"a","de":"die"},{"id":"b","de":"der"},{"id":"c","de":"deren"},{"id":"d","de":"dessen"}],"correct":"c","explanationAr":"**deren** = ضمير الموصول في حالة الإضافة (Genitiv) للمؤنّث/الجمع. (Lehrkraft مؤنّث). يربط الاسم باسم آخر مملوك (\"التي طرقها …\")."},{"id":"sb3","contextDe":"Es wird gefordert, dass Lehrer besser ___ werden.","blank":"Passiv","options":[{"id":"a","de":"ausgebildet"},{"id":"b","de":"ausbilden"},{"id":"c","de":"auszubilden"},{"id":"d","de":"ausbildet"}],"correct":"a","explanationAr":"**Passiv: werden + Partizip II**. هنا المطلوب أن يُدرَّب المعلّمون (لا أن يدرّبوا غيرهم). werden + ausgebildet = passiv presente."},{"id":"sb4","contextDe":"Die Reform muss endlich ___ werden, sonst bleibt die Schule rückständig.","blank":"Verb","options":[{"id":"a","de":"durchgeführt"},{"id":"b","de":"durchgeführen"},{"id":"c","de":"durchführen"},{"id":"d","de":"durchgeführet"}],"correct":"a","explanationAr":"**Partizip II: durchgeführt** (بدون -et). الفعل \"durchführen\" هو فعل قابل للفصل، لكن في Partizip II نضع -ge- بين durch- و -führt."}],"schreiben":{"id":"schreiben-1","topicAr":"كتابة رأي حول الرقمنة في المدارس","topicDe":"Forumsbeitrag: Tablets im Unterricht — sinnvoll oder schädlich?","contextDe":"In einem Bildungsforum lesen Sie eine Diskussion zur Digitalisierung der Schulen. Schreiben Sie einen Beitrag (150–200 Wörter), in dem Sie:","bulletPoints":["Ihre Meinung zur Digitalisierung darlegen.","Mindestens zwei Argumente begründen.","Ein konkretes Beispiel anführen.","Einen praktischen Vorschlag machen."],"redemittel":["Meiner Ansicht nach …","Ein zentrales Argument ist, dass …","Aus meiner Schulzeit erinnere ich mich, dass …","Andererseits darf man nicht vergessen, dass …","Mein Vorschlag wäre, …","Zusammenfassend lässt sich sagen, dass …"],"sampleEssayDe":"Liebe Forumsmitglieder,\n\ndie Digitalisierung der Schulen ist ein wichtiges Thema unserer Zeit. Meiner Ansicht nach sollten Tablets gezielt eingesetzt werden, aber traditionelle Methoden nicht ersetzen.\n\nEin zentrales Argument für digitale Geräte ist die individuelle Förderung. Lernprogramme können Aufgaben an das Niveau jedes Schülers anpassen. Aus meiner Schulzeit erinnere ich mich, dass schwächere Mitschüler oft nicht mitkamen, während andere unterfordert waren — eine App hätte hier helfen können.\n\nAndererseits darf man nicht vergessen, dass das Schreiben mit der Hand wichtige kognitive Fähigkeiten trainiert. Studien zeigen, dass handgeschriebene Notizen besser im Gedächtnis bleiben.\n\nMein Vorschlag wäre daher ein Mischmodell: zwei bis drei digitale Stunden pro Woche, der Rest klassisch mit Heft und Tafel. Außerdem müssten Lehrer regelmäßig geschult werden, denn ohne pädagogisches Konzept bleibt jede Technik nutzlos.\n\nZusammenfassend lässt sich sagen, dass digitale Bildung eine Chance ist — aber nur, wenn sie ergänzend und mit Augenmaß genutzt wird.","sampleEssayAr":"منشور حول الرقمنة في التعليم: الموقف هو أنّ الأجهزة الرقميّة يجب أن تُستخدم بشكل هادف لكن دون أن تحلّ محلّ الطرق التقليديّة. الحجج: التعليم الفردي وفرص التطوير، مقابل أهمّية الكتابة باليد. الاقتراح: نموذج مختلط + تدريب المعلّمين."},"sprechen":[{"id":"sp1","partAr":"الجزء 1 — التخطيط معاً","partDe":"Teil 1: Etwas gemeinsam planen","topicAr":"تنظيم يوم مفتوح في المدرسة","topicDe":"Einen Schultag der offenen Tür organisieren","redemittel":["Wir könnten das so organisieren, dass …","Was hältst du davon, wenn …?","Eine gute Idee wäre …","Sollten wir nicht zuerst …?"],"sampleAnswerDe":"A: Wir könnten den Tag so organisieren, dass jede Klasse einen Stand vorbereitet. Was hältst du davon?\n\nB: Eine gute Idee. Sollten wir nicht zuerst die Themen festlegen? Vielleicht ein Stand für jedes Fach.\n\nA: Genau. Und vormittags könnten Eltern in den Unterricht kommen, nachmittags gibt es Aufführungen im Saal.\n\nB: Einverstanden. Ich übernehme die Einladungen, du sprichst mit den Lehrkräften?"},{"id":"sp2","partAr":"الجزء 2 — Vortrag","partDe":"Teil 2: Vortrag","topicAr":"دور الواجبات المنزليّة في التعلّم","topicDe":"Die Rolle von Hausaufgaben im Lernprozess","redemittel":["In meinem Vortrag möchte ich auf … eingehen.","Erstens … Zweitens … Drittens …","Ein konkretes Beispiel dafür ist …","Abschließend möchte ich betonen, dass …"],"sampleAnswerDe":"In meinem Vortrag möchte ich auf die Rolle der Hausaufgaben eingehen. Erstens festigen Hausaufgaben das Gelernte; ohne Wiederholung bleibt wenig hängen. Zweitens fördern sie Selbstständigkeit, weil Schüler ohne ständige Anleitung arbeiten müssen. Drittens — und das ist umstritten — können sie aber auch Stress verursachen, vor allem in Familien ohne Unterstützungsmöglichkeit. Ein konkretes Beispiel: In Finnland gibt es kaum Hausaufgaben, und trotzdem schneiden die Schüler gut ab. Abschließend möchte ich betonen, dass die Qualität wichtiger ist als die Quantität: wenige sinnvolle Aufgaben schlagen viele mechanische."}]},{"id":"telc-b2-5","titleAr":"نموذج 5 — الرقمنة والتكنولوجيا","titleDe":"Modelltest 5 — Digitalisierung & Technologie","level":"B2","durationMin":165,"readingPassages":[{"id":"lese-1","titleDe":"Künstliche Intelligenz: Segen oder Bedrohung?","textDe":"Künstliche Intelligenz (KI) hat in den letzten Jahren rasante Fortschritte gemacht. Was vor wenigen Jahren noch Science-Fiction war, ist heute Alltag: Sprachassistenten, automatische Übersetzungen, medizinische Diagnosen — alles mit Hilfe von Algorithmen, die aus riesigen Datenmengen lernen. Befürworter sehen darin eine Revolution, die Krankheiten heilen, den Klimawandel bekämpfen und langweilige Routinearbeiten ersetzen wird.\n\nDoch die Sorgen wachsen ebenso schnell. Experten warnen vor dem Verlust von Millionen Arbeitsplätzen, vor der Manipulation öffentlicher Meinungen durch sogenannte Deepfakes und vor dem Missbrauch persönlicher Daten. Eine Studie des Weltwirtschaftsforums geht davon aus, dass bis 2027 weltweit etwa 83 Millionen Stellen wegfallen werden — gleichzeitig sollen aber 69 Millionen neue entstehen, vorwiegend in Bereichen wie Datenanalyse und KI-Entwicklung.\n\nDie Politik steht vor einer großen Herausforderung. Während die EU mit dem AI Act erste klare Regeln schafft, hinken viele Länder noch hinterher. Datenschützer fordern strengere Gesetze, doch Wirtschaftsverbände warnen vor zu viel Bürokratie, die Innovationen abwürgen könnte. Klar ist nur eines: Wer den Wandel verschläft, wird ihn nicht mehr aufholen können.","questions":[{"id":"q1","promptDe":"Wie schätzen Befürworter die KI ein?","options":[{"id":"a","de":"Als Modeerscheinung."},{"id":"b","de":"Als Revolution mit großem Nutzen."},{"id":"c","de":"Als überschätzte Technik."},{"id":"d","de":"Als Gefahr für die Demokratie."}],"correct":"b","explanationAr":"الإجابة (B): \"Befürworter sehen darin eine Revolution, die Krankheiten heilen … wird\" — يرونها ثورة بفوائد عظيمة (طبيّة، مناخيّة، عمل)."},{"id":"q2","promptDe":"Was sagt die Studie des Weltwirtschaftsforums voraus?","options":[{"id":"a","de":"83 Millionen neue Jobs werden entstehen."},{"id":"b","de":"83 Millionen Jobs verschwinden, 69 Millionen entstehen."},{"id":"c","de":"Alle Jobs werden ersetzt werden."},{"id":"d","de":"Die Arbeitslosenquote wird auf 50 % steigen."}],"correct":"b","explanationAr":"الإجابة (B): النصّ بالأرقام — 83 مليون وظيفة ستختفي + 69 مليون وظيفة جديدة ستنشأ. صافي الفقدان: 14 مليون. لكن المهارات المطلوبة ستختلف."},{"id":"q3","promptDe":"Was sind Deepfakes?","options":[{"id":"a","de":"Tiefe Lerntechniken."},{"id":"b","de":"Manipulation öffentlicher Meinungen mit gefälschten Inhalten."},{"id":"c","de":"Eine neue Programmiersprache."},{"id":"d","de":"Ein Datenschutzkonzept."}],"correct":"b","explanationAr":"الإجابة (B): النصّ يقول \"Manipulation öffentlicher Meinungen durch sogenannte Deepfakes\" — تلاعب بالرأي العامّ عبر مقاطع/صور مزيّفة باستخدام الذكاء الاصطناعي."},{"id":"q4","promptDe":"Was tut die EU?","options":[{"id":"a","de":"Sie verbietet KI komplett."},{"id":"b","de":"Sie hat keine Position."},{"id":"c","de":"Sie hat mit dem AI Act erste Regeln geschaffen."},{"id":"d","de":"Sie investiert nur in Forschung."}],"correct":"c","explanationAr":"الإجابة (C): \"die EU mit dem AI Act erste klare Regeln schafft\" — قانون الذكاء الاصطناعي الأوروبي 2024، أوّل تشريع شامل في العالم لتنظيم KI."},{"id":"q5","promptDe":"Was warnen die Wirtschaftsverbände?","options":[{"id":"a","de":"Vor zu wenig Datenschutz."},{"id":"b","de":"Vor zu viel Bürokratie, die Innovation hemmt."},{"id":"c","de":"Vor steigenden Energiepreisen."},{"id":"d","de":"Vor Personalmangel."}],"correct":"b","explanationAr":"الإجابة (B): \"Wirtschaftsverbände warnen vor zu viel Bürokratie, die Innovationen abwürgen könnte\" — البيروقراطيّة الزائدة قد تخنق الابتكار."}]}],"sprachbausteine":[{"id":"sb1","contextDe":"Trotz der Risiken halte ich KI ___ wertvoll.","blank":"Modaladverb","options":[{"id":"a","de":"für"},{"id":"b","de":"als"},{"id":"c","de":"wie"},{"id":"d","de":"an"}],"correct":"a","explanationAr":"**halten + Akkusativ + für** = يعتبر/يحسب شيئاً بصفة معيّنة. (Ich halte ihn für klug). تعبير ثابت لإبداء التقييم. (als يستخدم بعد bezeichnen / sehen)."},{"id":"sb2","contextDe":"Die Daten ___ vom Algorithmus analysiert.","blank":"Passiv","options":[{"id":"a","de":"werden"},{"id":"b","de":"sind"},{"id":"c","de":"haben"},{"id":"d","de":"wurden gewesen"}],"correct":"a","explanationAr":"**Vorgangspassiv: werden + Partizip II**. (البيانات تُحلَّل من قِبل الخوارزميّة). sind + analysiert يكون Zustandspassiv (الحالة بعد التحليل) — معنى مختلف."},{"id":"sb3","contextDe":"Wenn die KI hätte korrekt programmiert ___, wäre der Fehler nicht passiert.","blank":"Konjunktiv II Plusquamperfekt","options":[{"id":"a","de":"werden"},{"id":"b","de":"worden"},{"id":"c","de":"sein"},{"id":"d","de":"gewesen"}],"correct":"b","explanationAr":"**Konjunktiv II Plusquamperfekt Passiv**: hätte + Partizip II + worden. شرط افتراضي ماضي مع مبني للمجهول. (worden ≠ geworden في المبني للمجهول)."},{"id":"sb4","contextDe":"Diese Technologie ist ___ entwickelt worden, um Pflegekräfte zu entlasten.","blank":"Adverb","options":[{"id":"a","de":"speziell"},{"id":"b","de":"besonders"},{"id":"c","de":"eigentlich"},{"id":"d","de":"allerdings"}],"correct":"a","explanationAr":"**speziell + um … zu** = خصّيصاً لـ. تعبير شائع للهدف المحدّد. (besonders = بشكل خاصّ، صفة، eigentlich = في الحقيقة، allerdings = ومع ذلك)."}],"schreiben":{"id":"schreiben-1","topicAr":"كتابة منشور رأي حول الذكاء الاصطناعي","topicDe":"Forumsbeitrag: Sollte KI im Beruf reguliert werden?","contextDe":"Sie haben in einem Online-Forum eine Diskussion zur KI-Regulierung im Berufsleben gelesen. Schreiben Sie einen Beitrag (150–200 Wörter), in dem Sie:","bulletPoints":["Ihre Position klar machen.","Mindestens zwei Argumente nennen.","Ein Beispiel aus Ihrem Umfeld geben.","Einen konkreten Lösungsvorschlag formulieren."],"redemittel":["Aus meiner Sicht ist klar, dass …","Ein Hauptgrund dafür ist, dass …","In meinem Beruf erlebe ich beispielsweise, dass …","Selbstverständlich gibt es auch Gegenstimmen, die …","Eine sinnvolle Lösung wäre, …","Letztlich kommt es darauf an, dass …"],"sampleEssayDe":"Liebe Forumsmitglieder,\n\ndie Diskussion über KI-Regulierung beschäftigt mich sehr. Aus meiner Sicht ist klar, dass wir Regeln brauchen — allerdings ohne den Fortschritt zu blockieren.\n\nEin Hauptgrund dafür ist der Schutz von Arbeitnehmern. Wenn Algorithmen über Bewerbungen oder Kündigungen entscheiden, müssen die Kriterien transparent sein. In meinem Beruf erlebe ich beispielsweise, dass Bewerbersoftware Lebensläufe automatisch sortiert — wer dann fälschlicherweise herausfällt, hat keine Chance auf ein Gespräch.\n\nSelbstverständlich gibt es auch Gegenstimmen, die vor zu strengen Regeln warnen. Sie befürchten, dass Innovation in andere Länder abwandern könnte. Diese Sorge ist nachvollziehbar, doch ohne Vertrauen werden Bürger neue Technologien gar nicht erst akzeptieren.\n\nEine sinnvolle Lösung wäre eine Kombination: klare Mindeststandards für Datenschutz und Erklärbarkeit, kombiniert mit staatlicher Förderung von Forschung. Außerdem sollten Unternehmen verpflichtet sein, KI-Entscheidungen menschlich überprüfen zu lassen.\n\nLetztlich kommt es darauf an, dass Mensch und Maschine zusammenarbeiten — nicht gegeneinander.","sampleEssayAr":"منشور حول تنظيم الذكاء الاصطناعي في العمل: الموقف هو ضرورة وضع قواعد دون عرقلة التقدّم. الحجج: حماية العمّال + الشفافيّة في القرارات الآليّة. مثال: برامج فرز السير الذاتيّة. الحلّ: حدّ أدنى من المعايير + دعم البحث + إلزام بالمراجعة البشريّة. الاستنتاج: التعاون بين الإنسان والآلة."},"sprechen":[{"id":"sp1","partAr":"الجزء 1 — التخطيط معاً","partDe":"Teil 1: Etwas gemeinsam planen","topicAr":"تنظيم ورشة عمل عن الذكاء الاصطناعي للموظّفين","topicDe":"Einen KI-Workshop für Mitarbeiter organisieren","redemittel":["Mein Vorschlag wäre, …","Was meinst du dazu?","Sinnvoll wäre auch, …","Lass uns das so machen: …"],"sampleAnswerDe":"A: Mein Vorschlag wäre, den Workshop in zwei Teile zu gliedern: erst Theorie, dann praktische Übungen. Was meinst du dazu?\n\nB: Gute Idee. Sinnvoll wäre auch, Beispiele aus unserem Alltag zu zeigen — z.B. wie KI in unserer Buchhaltungssoftware schon arbeitet.\n\nA: Lass uns das so machen: Vormittags Grundlagen, nachmittags Workshops in Kleingruppen. Du übernimmst die Einladung an die Geschäftsführung?\n\nB: Einverstanden. Ich kümmere mich um Technik und Catering."},{"id":"sp2","partAr":"الجزء 2 — Vortrag","partDe":"Teil 2: Vortrag","topicAr":"الذكاء الاصطناعي في الحياة اليوميّة","topicDe":"KI im Alltag: Chancen und Grenzen","redemittel":["Heute möchte ich über … sprechen.","Auf der einen Seite … auf der anderen Seite …","Ein typisches Beispiel ist …","Zum Schluss komme ich zu folgendem Fazit: …"],"sampleAnswerDe":"Heute möchte ich über die Rolle der KI im Alltag sprechen. Auf der einen Seite hilft uns KI bei vielen kleinen Aufgaben: Navigation, Übersetzung, Filmempfehlungen — kaum jemand käme ohne sie aus. Auf der anderen Seite verlieren wir aber auch Fähigkeiten: Wer kennt heute noch Telefonnummern auswendig? Ein typisches Beispiel ist die Sprachsteuerung im Auto, die uns aufmerksamer fahren lässt — gleichzeitig vertrauen wir blind den Vorschlägen. Zum Schluss komme ich zu folgendem Fazit: KI ist ein nützliches Werkzeug, aber wir sollten sie bewusst nutzen und nicht alle Entscheidungen abgeben."}]}]'''));


final List<Map<String, dynamic>> b2Essays = [{'id': 'soziale-medien', 'titleAr': 'وسائل التواصل الاجتماعي', 'titleDe': 'Soziale Medien', 'promptAr': 'هل وسائل التواصل (فيسبوك، إنستغرام، تيك توك) لها تأثير سلبي أكثر من إيجابي على المجتمع؟ ناقش رأيك.', 'promptDe': 'Haben soziale Medien (Facebook, Instagram, TikTok) mehr negative als positive Auswirkungen auf die Gesellschaft? Begründen Sie Ihre Meinung.', 'pro': [{'pointAr': 'تساعد في البقاء على تواصل مع الأهل والأصدقاء البعيدين.', 'pointDe': 'Sie helfen, mit Familie und Freunden in Kontakt zu bleiben.'}, {'pointAr': 'وصول سريع للمعلومات والأخبار.', 'pointDe': 'Schneller Zugang zu Informationen und Nachrichten.'}, {'pointAr': 'فرص عمل وتسويق للشركات الصغيرة.', 'pointDe': 'Geschäftsmöglichkeiten für kleine Unternehmen.'}], 'contra': [{'pointAr': 'إدمان وفقدان الوقت بدلاً من النشاطات المفيدة.', 'pointDe': 'Suchtgefahr und Zeitverschwendung.'}, {'pointAr': 'مقارنة الذات مع الآخرين تسبّب الاكتئاب.', 'pointDe': 'Vergleich mit anderen führt zu Depressionen.'}, {'pointAr': 'انتشار الأخبار الكاذبة (Fake News).', 'pointDe': 'Verbreitung von Fake News.'}], 'goldenPhrases': [{'de': 'Heutzutage ist es kaum vorstellbar, ohne soziale Medien zu leben.', 'ar': 'اليوم من الصعب تصوّر الحياة بدون وسائل تواصل.'}, {'de': 'Auf der einen Seite … auf der anderen Seite …', 'ar': 'من ناحية... ومن ناحية أخرى...'}, {'de': 'Studien zeigen, dass …', 'ar': 'الدراسات تُظهر أنّ...'}, {'de': 'Zusammenfassend lässt sich sagen, dass …', 'ar': 'باختصار، يمكن القول إنّ...'}], 'modelEssay': 'Heutzutage benutzen fast alle Menschen soziale Medien wie Instagram oder TikTok. Aber sind sie wirklich gut für unsere Gesellschaft?\n\nAuf der einen Seite haben sie viele Vorteile: Wir können mit Familie im Ausland in Kontakt bleiben, schnell an Informationen kommen und sogar Geld verdienen.\n\nAuf der anderen Seite gibt es ernste Nachteile. Viele junge Menschen vergleichen sich ständig mit anderen und werden dadurch unzufrieden. Außerdem verbreiten sich Fake News sehr schnell.\n\nMeiner Meinung nach überwiegen die Nachteile, wenn man unkontrolliert nutzt. Mit klaren Zeitlimits können soziale Medien jedoch sehr nützlich sein.', 'tips': ['افتح بسؤال أو حقيقة عامة لتجذب القارئ.', 'استخدم "Auf der einen Seite … auf der anderen Seite …".', 'أنهِ برأيك الواضح + اقتراح.']}, {'id': 'umwelt', 'titleAr': 'حماية البيئة', 'titleDe': 'Umweltschutz', 'promptAr': 'هل يجب أن تكون حماية البيئة مسؤولية الأفراد أم الحكومات؟ اكتب رأيك.', 'promptDe': 'Soll Umweltschutz Aufgabe der Einzelnen oder des Staates sein? Schreiben Sie Ihre Meinung.', 'pro': [{'pointAr': 'الفرد يستطيع أن يبدأ فوراً بتقليل البلاستيك.', 'pointDe': 'Jeder kann sofort weniger Plastik verbrauchen.'}, {'pointAr': 'استخدام الدراجة بدل السيارة.', 'pointDe': 'Fahrrad statt Auto fahren.'}, {'pointAr': 'فرز النفايات في البيت.', 'pointDe': 'Mülltrennung zu Hause.'}], 'contra': [{'pointAr': 'الحكومة فقط تستطيع وضع قوانين على المصانع الكبيرة.', 'pointDe': 'Nur der Staat kann Gesetze für Industrie machen.'}, {'pointAr': 'الفرد لا يستطيع تغيير وسائل النقل العامة.', 'pointDe': 'Einzelne können den ÖPNV nicht ändern.'}, {'pointAr': 'الدعم المالي للطاقة المتجددة من الحكومة.', 'pointDe': 'Förderung erneuerbarer Energien durch den Staat.'}], 'goldenPhrases': [{'de': 'Der Klimawandel ist eine der größten Herausforderungen unserer Zeit.', 'ar': 'تغيّر المناخ من أكبر تحدّيات عصرنا.'}, {'de': 'Sowohl der Staat als auch die Bürger müssen handeln.', 'ar': 'يجب أن تتحرّك الدولة والمواطنون معاً.'}, {'de': 'In meinem Alltag versuche ich, …', 'ar': 'في حياتي اليومية أحاول أن...'}, {'de': 'Ich bin der Meinung, dass beide Seiten verantwortlich sind.', 'ar': 'أرى أن كلا الجهتين مسؤولة.'}], 'modelEssay': 'Der Klimawandel ist eine der größten Herausforderungen unserer Zeit. Aber wer ist verantwortlich – der Staat oder jeder von uns?\n\nIch bin der Meinung, dass beide Seiten gemeinsam handeln müssen. Der Staat muss klare Regeln für Industrie und Verkehr machen, weil ein einzelner Bürger das nicht tun kann.\n\nGleichzeitig sind kleine Schritte im Alltag sehr wichtig. In meiner Familie zum Beispiel trennen wir den Müll, kaufen regional ein und fahren oft mit dem Fahrrad.\n\nZusammenfassend kann ich sagen: Umweltschutz funktioniert nur, wenn der Staat Gesetze macht und die Bürger im Alltag mitmachen.', 'tips': ['استخدم "sowohl … als auch" لإظهار توازن.', 'اذكر مثالاً من حياتك (= نقاط إضافية).', 'اختم بحلّ مشترك.']}, {'id': 'sport', 'titleAr': 'الرياضة في المدارس', 'titleDe': 'Sport in der Schule', 'promptAr': 'هل يجب أن تكون مادة الرياضة إجبارية في المدرسة كل يوم؟ ناقش.', 'promptDe': 'Soll Sport jeden Tag in der Schule Pflichtfach sein? Diskutieren Sie.', 'pro': [{'pointAr': 'يحسّن الصحة الجسدية والنفسية للأطفال.', 'pointDe': 'Verbessert körperliche und psychische Gesundheit.'}, {'pointAr': 'يقلّل من السمنة عند الأطفال.', 'pointDe': 'Reduziert Übergewicht bei Kindern.'}, {'pointAr': 'يعلّم العمل الجماعي.', 'pointDe': 'Lehrt Teamarbeit.'}], 'contra': [{'pointAr': 'وقت أقل للمواد الأكاديمية.', 'pointDe': 'Weniger Zeit für akademische Fächer.'}, {'pointAr': 'بعض الأطفال لا يحبّون الرياضة وقد يشعرون بالإحباط.', 'pointDe': 'Manche Kinder mögen Sport nicht und fühlen sich frustriert.'}, {'pointAr': 'التكاليف الإضافية على المدارس.', 'pointDe': 'Zusätzliche Kosten für Schulen.'}], 'goldenPhrases': [{'de': 'Bewegung ist für Kinder besonders wichtig.', 'ar': 'الحركة مهمّة جداً للأطفال.'}, {'de': 'Es gibt sowohl Vor- als auch Nachteile.', 'ar': 'هناك مزايا وعيوب.'}, {'de': 'Eine Stunde Sport pro Tag wäre vielleicht zu viel.', 'ar': 'ساعة رياضة يومياً ربما كثيرة.'}, {'de': 'Ein Kompromiss könnte sein, …', 'ar': 'الحل الوسط قد يكون...'}], 'modelEssay': 'Bewegung ist für Kinder besonders wichtig. Trotzdem stellt sich die Frage: Soll Sport jeden Tag Pflichtfach sein?\n\nAuf der einen Seite hilft tägliche Bewegung gegen Übergewicht und stärkt das Immunsystem. Außerdem lernen Kinder, im Team zu arbeiten – das ist auch im späteren Leben nützlich.\n\nAuf der anderen Seite haben Schüler heute schon viele Fächer. Eine Stunde Sport pro Tag würde Zeit für Mathe oder Deutsch wegnehmen.\n\nEin Kompromiss könnte sein: Drei Sportstunden pro Woche plus eine kurze Bewegungspause jeden Tag. So bleiben die Kinder fit, ohne andere Fächer zu verpassen.', 'tips': ['استخدم "trotzdem" بعد جملة عامة.', 'قدّم 2 نقطة من كل جانب على الأقل.', 'أنهِ بحلّ متوازن.']}, {'id': 'integration', 'titleAr': 'الاندماج في المجتمع الألماني', 'titleDe': 'Integration in Deutschland', 'promptAr': 'ما هو أهم شيء لاندماج اللاجئين في ألمانيا؟ اللغة، العمل، أم الصداقات؟', 'promptDe': 'Was ist am wichtigsten für die Integration von Geflüchteten in Deutschland? Sprache, Arbeit oder Freundschaften?', 'pro': [{'pointAr': 'اللغة هي مفتاح كل شيء.', 'pointDe': 'Sprache ist der Schlüssel zu allem.'}, {'pointAr': 'العمل يعطي شعوراً بالاستقلال.', 'pointDe': 'Arbeit gibt ein Gefühl der Unabhängigkeit.'}, {'pointAr': 'الصداقات الألمانية تعلّم الثقافة.', 'pointDe': 'Deutsche Freundschaften lehren die Kultur.'}], 'contra': [{'pointAr': 'بدون لغة لا يوجد عمل.', 'pointDe': 'Ohne Sprache gibt es keine Arbeit.'}, {'pointAr': 'بعض الأشخاص لديهم خبرة بدون لغة.', 'pointDe': 'Manche haben Erfahrung ohne Sprache.'}, {'pointAr': 'الصداقات تساعد على تعلّم اللغة.', 'pointDe': 'Freundschaften helfen, die Sprache zu lernen.'}], 'goldenPhrases': [{'de': 'Aus eigener Erfahrung kann ich sagen, …', 'ar': 'من تجربتي الشخصية...'}, {'de': 'Die deutsche Sprache ist der Schlüssel zur Integration.', 'ar': 'اللغة الألمانية هي مفتاح الاندماج.'}, {'de': 'Allerdings ist auch wichtig, …', 'ar': 'مع ذلك من المهم أيضاً...'}, {'de': 'Letztendlich hängen alle drei Bereiche zusammen.', 'ar': 'في النهاية المجالات الثلاثة مترابطة.'}], 'modelEssay': 'Aus eigener Erfahrung als Flüchtling in Deutschland kann ich sagen: Alle drei Punkte sind wichtig, aber die Sprache ist der wichtigste.\n\nOhne Deutschkenntnisse kann man nicht arbeiten und keine echten Freundschaften aufbauen. Beim Arzt, im Amt und im Job braucht man die Sprache jeden Tag.\n\nAllerdings ist auch wichtig, schnell zu arbeiten oder eine Ausbildung zu beginnen. Das gibt einem das Gefühl, etwas Sinnvolles zu tun.\n\nFreundschaften mit Deutschen helfen am Ende dabei, die Sprache zu üben und die Kultur zu verstehen.\n\nLetztendlich hängen alle drei Bereiche zusammen, aber ohne Sprache geht gar nichts.', 'tips': ['افتح بـ "Aus eigener Erfahrung" — يمنح المصداقية.', 'رتّب أولوياتك بوضوح.', 'اختم بربط النقاط الثلاث.']}, {'id': 'gesundheit', 'titleAr': 'الأكل الصحي والبدائل النباتية', 'titleDe': 'Gesunde Ernährung und vegetarische Alternativen', 'promptAr': 'هل الأكل النباتي أفضل من اللحوم؟ ناقش الإيجابيات والسلبيات.', 'promptDe': 'Ist vegetarische Ernährung besser als Fleisch? Diskutieren Sie Vor- und Nachteile.', 'pro': [{'pointAr': 'أفضل للبيئة (انبعاثات أقل).', 'pointDe': 'Besser für die Umwelt (weniger CO2).'}, {'pointAr': 'يقلّل أمراض القلب.', 'pointDe': 'Senkt Herzkrankheiten.'}, {'pointAr': 'حماية للحيوانات.', 'pointDe': 'Tierschutz.'}], 'contra': [{'pointAr': 'نقص بعض الفيتامينات (B12, Eisen).', 'pointDe': 'Mangel an Vitaminen (B12, Eisen).'}, {'pointAr': 'بعض المنتجات النباتية باهظة الثمن.', 'pointDe': 'Manche pflanzlichen Produkte sind teuer.'}, {'pointAr': 'صعوبة الالتزام في المطاعم والمناسبات.', 'pointDe': 'Schwierigkeiten in Restaurants und bei Festen.'}], 'goldenPhrases': [{'de': 'Immer mehr Menschen entscheiden sich für …', 'ar': 'أناس أكثر فأكثر يختارون...'}, {'de': 'Ein wichtiger Aspekt ist die Gesundheit.', 'ar': 'الصحة جانب مهم.'}, {'de': 'Eine ausgewogene Ernährung ist entscheidend.', 'ar': 'النظام الغذائي المتوازن أساسي.'}, {'de': 'Mein Fazit: …', 'ar': 'خلاصتي: ...'}], 'modelEssay': 'Immer mehr Menschen in Deutschland entscheiden sich für vegetarisches Essen. Aber ist es wirklich besser als Fleisch?\n\nEin klarer Vorteil ist die Umwelt: Tierhaltung verursacht viele Emissionen, deshalb hilft vegetarisches Essen dem Klima. Auch für die Gesundheit ist es oft besser, weil weniger Cholesterin und mehr Gemüse gegessen werden.\n\nAllerdings gibt es auch Risiken. Wer nur vegetarisch isst, muss aufpassen, dass er genug Eisen und Vitamin B12 bekommt.\n\nMein Fazit: Eine ausgewogene Ernährung mit viel Gemüse und wenig Fleisch ist wahrscheinlich der beste Weg.', 'tips': ['افتح بإحصائية أو ملاحظة عامة.', 'استخدم "deshalb" بعد علاقة سبب-نتيجة.', 'اختم بـ "Mein Fazit:".']}, {'id': 'arbeit-homeoffice', 'titleAr': 'العمل من المنزل', 'titleDe': 'Homeoffice', 'promptAr': 'هل تفضّل العمل من المنزل أم من المكتب؟ ولماذا؟', 'promptDe': 'Möchten Sie lieber von zu Hause oder im Büro arbeiten? Warum?', 'pro': [{'pointAr': 'توفير الوقت في الذهاب والإياب.', 'pointDe': 'Zeitersparnis durch keinen Arbeitsweg.'}, {'pointAr': 'مرونة أكبر للأمومة/الأبوة.', 'pointDe': 'Mehr Flexibilität für Familie.'}, {'pointAr': 'تركيز أعلى بدون ضوضاء.', 'pointDe': 'Höhere Konzentration ohne Lärm.'}], 'contra': [{'pointAr': 'العزلة الاجتماعية.', 'pointDe': 'Soziale Isolation.'}, {'pointAr': 'صعوبة الفصل بين العمل والحياة الشخصية.', 'pointDe': 'Schwierige Trennung von Arbeit und Freizeit.'}, {'pointAr': 'مشاكل تقنية في المنزل.', 'pointDe': 'Technische Probleme zu Hause.'}], 'goldenPhrases': [{'de': 'Seit der Pandemie ist Homeoffice viel beliebter.', 'ar': 'منذ الجائحة أصبح العمل من المنزل أكثر شيوعاً.'}, {'de': 'Persönlich bevorzuge ich …', 'ar': 'شخصياً أفضّل...'}, {'de': 'Ein Mix aus beidem wäre ideal.', 'ar': 'مزيج من الاثنين سيكون مثالياً.'}, {'de': 'Es kommt auf den Beruf an.', 'ar': 'الأمر يعتمد على المهنة.'}], 'modelEssay': 'Seit der Pandemie ist Homeoffice in vielen Berufen normal geworden. Aber ist es wirklich besser?\n\nFür mich hat das Arbeiten zu Hause klare Vorteile. Ich spare jeden Tag eine Stunde Fahrt und kann besser auf meine Kinder aufpassen.\n\nAllerdings fehlen mir die persönlichen Gespräche mit Kollegen. Außerdem ist es schwer, am Abend abzuschalten – die Arbeit ist immer im Nebenraum.\n\nPersönlich bevorzuge ich einen Mix: drei Tage zu Hause, zwei Tage im Büro. So habe ich Flexibilität, aber auch sozialen Kontakt.\n\nLetztendlich hängt es vom Beruf ab.', 'tips': ['اختر موقفاً واضحاً (مع/ضد/مزيج).', 'دعّم بمثال شخصي.', 'اعترف بالنقطة المعاكسة لتظهر أنك تفكّر بتوازن.']}, {'id': 'lernen-online', 'titleAr': 'التعلّم عبر الإنترنت', 'titleDe': 'Online-Lernen', 'promptAr': 'هل التعلّم عبر الإنترنت يستطيع أن يحلّ محل المدرسة التقليدية؟', 'promptDe': 'Kann Online-Lernen den traditionellen Schulunterricht ersetzen?', 'pro': [{'pointAr': 'مرن — يمكن التعلّم في أي وقت.', 'pointDe': 'Flexibel – jederzeit lernbar.'}, {'pointAr': 'تكلفة أقل (بدون نقل).', 'pointDe': 'Niedrigere Kosten (ohne Transport).'}, {'pointAr': 'وصول لمعلّمين عالميين.', 'pointDe': 'Zugang zu weltweiten Lehrern.'}], 'contra': [{'pointAr': 'نقص التواصل الاجتماعي مع الزملاء.', 'pointDe': 'Weniger sozialer Kontakt.'}, {'pointAr': 'يحتاج انضباطاً ذاتياً عالياً.', 'pointDe': 'Erfordert hohe Selbstdisziplin.'}, {'pointAr': 'مشاكل تقنية وفجوات اجتماعية.', 'pointDe': 'Technische Probleme und soziale Ungleichheit.'}], 'goldenPhrases': [{'de': 'In Zukunft wird das Lernen anders aussehen.', 'ar': 'في المستقبل سيكون التعلّم مختلفاً.'}, {'de': 'Online-Tools sind eine gute Ergänzung.', 'ar': 'الأدوات الإلكترونية إضافة جيدة.'}, {'de': 'Junge Kinder brauchen besonders den persönlichen Kontakt.', 'ar': 'الأطفال الصغار خاصة يحتاجون التواصل المباشر.'}, {'de': 'Ich denke, beides hat seinen Platz.', 'ar': 'أعتقد أن لكليهما مكاناً.'}], 'modelEssay': 'In den letzten Jahren haben viele Schulen und Universitäten Online-Kurse eingeführt. Kann das die normale Schule ersetzen?\n\nEin großer Vorteil ist die Flexibilität: Schüler können ihr Tempo selbst bestimmen und Videos wiederholen, wenn sie etwas nicht verstehen.\n\nAllerdings fehlen viele wichtige Dinge online. Junge Kinder brauchen den direkten Kontakt mit Lehrern und Klassenkameraden, um soziale Fähigkeiten zu lernen. Außerdem haben nicht alle Familien einen Computer und schnelles Internet.\n\nIch denke, beides hat seinen Platz. Online-Lernen ist eine sehr gute Ergänzung, aber kein vollständiger Ersatz – besonders nicht für Kinder.', 'tips': ['استخدم "in den letzten Jahren" للسياق التاريخي.', 'فرّق بين الأطفال والكبار.', 'استخدم "Ergänzung" (إضافة) بدل "Ersatz" (بديل).']}, {'id': 'reisen', 'titleAr': 'السفر — هل ضروري للحياة؟', 'titleDe': 'Reisen – ist es notwendig?', 'promptAr': 'هل السفر إلى دول أخرى مهم لتطوير الإنسان؟', 'promptDe': 'Ist es wichtig, andere Länder zu bereisen, um sich persönlich weiterzuentwickeln?', 'pro': [{'pointAr': 'تعلّم لغات وثقافات جديدة.', 'pointDe': 'Neue Sprachen und Kulturen lernen.'}, {'pointAr': 'يفتح الذهن ويزيد التسامح.', 'pointDe': 'Erweitert den Horizont und fördert Toleranz.'}, {'pointAr': 'يقدّم تجارب لا تُنسى.', 'pointDe': 'Schafft unvergessliche Erlebnisse.'}], 'contra': [{'pointAr': 'مكلف للأشخاص ذوي الدخل المحدود.', 'pointDe': 'Teuer für Menschen mit niedrigem Einkommen.'}, {'pointAr': 'تأثير سيئ على البيئة (انبعاثات الطيران).', 'pointDe': 'Schädlich für die Umwelt (CO2 von Flugzeugen).'}, {'pointAr': 'يمكن تعلّم الثقافات من الكتب والإنترنت.', 'pointDe': 'Kulturen kann man auch aus Büchern lernen.'}], 'goldenPhrases': [{'de': 'Reisen bildet, sagt man.', 'ar': 'يقولون السفر يثقّف.'}, {'de': 'Aus meiner Sicht …', 'ar': 'من وجهة نظري...'}, {'de': 'Allerdings sollte man nicht vergessen, dass …', 'ar': 'لكن يجب ألاّ ننسى أنّ...'}, {'de': 'Ein Mittelweg könnte sein, …', 'ar': 'الحل الوسط قد يكون...'}], 'modelEssay': '"Reisen bildet", sagt man oft. Aber ist es wirklich notwendig, viele Länder zu besuchen, um sich weiterzuentwickeln?\n\nAus meiner Sicht hat Reisen viele Vorteile. Man lernt direkt eine andere Sprache, sieht, wie andere Menschen leben, und wird offener für Neues. Mein Onkel hat in der Türkei gelebt und kann jetzt ganz anders mit Kunden umgehen.\n\nAllerdings sollte man nicht vergessen, dass Reisen teuer ist und der Umwelt schadet. Wer keinen Pass oder kein Geld hat, kann trotzdem viel über andere Kulturen aus Büchern, Filmen und Begegnungen im eigenen Land lernen.\n\nEin Mittelweg ist also sinnvoll: nicht zu viel fliegen, aber wenn möglich, einmal im Leben ein anderes Land erleben.', 'tips': ['افتح بحكمة شائعة (Reisen bildet).', 'اقتبس مثالاً عن شخص قريب.', 'اقترح "Mittelweg" — حلاً وسطاً.']}, {'id': 'geld-glueck', 'titleAr': 'هل المال يجلب السعادة؟', 'titleDe': 'Macht Geld glücklich?', 'promptAr': 'هل المال هو أساس السعادة في الحياة؟', 'promptDe': 'Ist Geld die Grundlage des Glücks im Leben?', 'pro': [{'pointAr': 'يوفّر الأمان والاستقرار.', 'pointDe': 'Sicherheit und Stabilität.'}, {'pointAr': 'يسمح بالسفر والعلاج.', 'pointDe': 'Ermöglicht Reisen und gute medizinische Versorgung.'}, {'pointAr': 'يقلّل الضغط النفسي.', 'pointDe': 'Reduziert Stress.'}], 'contra': [{'pointAr': 'الأصدقاء والعائلة أهم.', 'pointDe': 'Freunde und Familie sind wichtiger.'}, {'pointAr': 'الصحة لا تُشترى بالمال.', 'pointDe': 'Gesundheit kann man nicht kaufen.'}, {'pointAr': 'المال الكثير يجلب أحياناً مشاكل.', 'pointDe': 'Viel Geld bringt manchmal Probleme.'}], 'goldenPhrases': [{'de': 'Es heißt oft, dass Geld nicht glücklich macht.', 'ar': 'يقال إن المال لا يجلب السعادة.'}, {'de': 'Dennoch ist Geld bis zu einem gewissen Punkt wichtig.', 'ar': 'مع ذلك المال مهم حتى نقطة معيّنة.'}, {'de': 'Gesundheit, Familie und Sinn im Leben sind unbezahlbar.', 'ar': 'الصحة والعائلة ومعنى الحياة لا تُقدّر بثمن.'}, {'de': 'Wahre Zufriedenheit kommt von innen.', 'ar': 'الرضا الحقيقي يأتي من الداخل.'}], 'modelEssay': 'Es heißt oft: "Geld macht nicht glücklich." Aber stimmt das wirklich?\n\nAuf der einen Seite ist Geld wichtig, weil es Sicherheit gibt. Mit genug Geld kann man die Miete bezahlen, gut essen und sich Bildung leisten. Wer große finanzielle Sorgen hat, ist selten glücklich.\n\nAuf der anderen Seite zeigen viele Beispiele, dass sehr reiche Menschen nicht automatisch glücklicher sind. Familie, Freunde und Gesundheit kann man nicht kaufen.\n\nMeiner Meinung nach macht Geld bis zu einem bestimmten Punkt glücklich – nämlich bis man genug für ein normales Leben hat. Danach wird wahre Zufriedenheit aus Beziehungen und einem Sinn im Leben kommen.', 'tips': ['افتح بمقولة شعبية بين علامات اقتباس.', 'استخدم "bis zu einem gewissen Punkt" للنقاش الدقيق.', 'استخدم Konnektoren: dennoch, jedoch, allerdings.']}, {'id': 'auto-stadt', 'titleAr': 'حظر السيارات في وسط المدن', 'titleDe': 'Autoverbot in der Innenstadt', 'promptAr': 'هل يجب منع السيارات في وسط المدن لحماية البيئة؟', 'promptDe': 'Soll man Autos in der Innenstadt verbieten, um die Umwelt zu schützen?', 'pro': [{'pointAr': 'هواء نظيف وأقل ضوضاء.', 'pointDe': 'Saubere Luft und weniger Lärm.'}, {'pointAr': 'مدينة آمنة للأطفال والمشاة.', 'pointDe': 'Sicherer für Kinder und Fußgänger.'}, {'pointAr': 'يدعم الدراجات والنقل العام.', 'pointDe': 'Fördert Fahrräder und ÖPNV.'}], 'contra': [{'pointAr': 'صعب لكبار السن وذوي الإعاقة.', 'pointDe': 'Schwierig für ältere und behinderte Menschen.'}, {'pointAr': 'يضرّ المحلات في الوسط.', 'pointDe': 'Schadet Geschäften in der Innenstadt.'}, {'pointAr': 'بعض المدن لا تملك نقلاً عاماً جيداً.', 'pointDe': 'Manche Städte haben schlechten ÖPNV.'}], 'goldenPhrases': [{'de': 'Viele europäische Städte haben bereits autofreie Zonen.', 'ar': 'كثير من المدن الأوروبية لديها مناطق خالية من السيارات.'}, {'de': 'Allerdings gibt es auch Probleme.', 'ar': 'لكن هناك مشاكل أيضاً.'}, {'de': 'Statt eines totalen Verbots, …', 'ar': 'بدل الحظر الكامل، ...'}, {'de': 'Ein moderner Ansatz wäre …', 'ar': 'النهج العصري هو ...'}], 'modelEssay': 'Viele europäische Städte wie Wien oder Kopenhagen haben bereits Bereiche ohne Autos. Soll Deutschland diesem Beispiel folgen?\n\nKlare Vorteile: weniger Abgase, weniger Lärm, mehr Platz für Kinder, Fahrräder und Cafés. In Köln haben Eltern weniger Angst, ihre Kinder allein in die Schule zu schicken.\n\nAllerdings darf man die Nachteile nicht vergessen. Ältere oder kranke Menschen brauchen oft das Auto. Auch viele Geschäftsbesitzer fürchten weniger Kunden.\n\nStatt eines totalen Verbots wäre ein moderner Ansatz besser: Nur Elektroautos und Lieferfahrzeuge dürfen in die Innenstadt. So bleibt die Mobilität für alle erhalten, aber die Luft wird sauberer.', 'tips': ['اذكر مثالاً من مدينة معروفة.', 'استخدم "Statt … wäre …" لتقديم بديل.', 'لا تتجاهل الفئات الضعيفة.']}, {'id': 'haustier', 'titleAr': 'الحيوانات الأليفة في الشقق', 'titleDe': 'Haustiere in Wohnungen', 'promptAr': 'هل من الجيد تربية كلاب وقطط في شقق صغيرة؟', 'promptDe': 'Ist es sinnvoll, Hunde und Katzen in kleinen Wohnungen zu halten?', 'pro': [{'pointAr': 'يخفّف الوحدة ويُسعد كبار السن.', 'pointDe': 'Reduziert Einsamkeit, glücklich für ältere Menschen.'}, {'pointAr': 'يعلّم الأطفال المسؤولية.', 'pointDe': 'Lehrt Kinder Verantwortung.'}, {'pointAr': 'حيوانات صغيرة (قطط) تتأقلم في الشقق.', 'pointDe': 'Kleine Tiere (Katzen) passen in Wohnungen.'}], 'contra': [{'pointAr': 'الكلاب الكبيرة تحتاج حديقة.', 'pointDe': 'Große Hunde brauchen einen Garten.'}, {'pointAr': 'تكاليف عالية (طبيب، طعام).', 'pointDe': 'Hohe Kosten (Tierarzt, Futter).'}, {'pointAr': 'مشاكل مع الجيران (ضوضاء، حساسية).', 'pointDe': 'Probleme mit Nachbarn (Lärm, Allergien).'}], 'goldenPhrases': [{'de': 'Viele Familien wünschen sich ein Haustier.', 'ar': 'كثير من العائلات تتمنّى حيواناً أليفاً.'}, {'de': 'Es kommt auf die Tierart an.', 'ar': 'الأمر يعتمد على نوع الحيوان.'}, {'de': 'Verantwortung gegenüber dem Tier ist wichtig.', 'ar': 'المسؤولية تجاه الحيوان مهمّة.'}, {'de': 'Wer keinen Platz oder keine Zeit hat, sollte kein Tier halten.', 'ar': 'من ليس لديه مكان أو وقت لا يجب أن يقتني حيواناً.'}], 'modelEssay': 'Viele Familien wünschen sich ein Haustier. Aber ist eine kleine Wohnung der richtige Platz dafür?\n\nEs kommt vor allem auf die Tierart an. Kleine Katzen oder Vögel können sich in einer Wohnung wohlfühlen, wenn sie genug Beschäftigung bekommen. Sie helfen besonders älteren Menschen gegen die Einsamkeit.\n\nAllerdings ist eine 50-Quadratmeter-Wohnung kein Platz für einen großen Hund. Solche Tiere brauchen jeden Tag viel Bewegung und einen Garten. Außerdem sind die Kosten für Tierarzt und Futter oft höher, als die Menschen denken.\n\nVerantwortung gegenüber dem Tier ist also wichtiger als der eigene Wunsch. Wer keinen Platz oder keine Zeit hat, sollte besser kein Tier halten.', 'tips': ['فرّق بين الكلاب والقطط.', 'اذكر التكاليف.', 'اختم بمبدأ المسؤولية.']}, {'id': 'ehrenamt', 'titleAr': 'العمل التطوعي', 'titleDe': 'Ehrenamtliche Arbeit', 'promptAr': 'هل يجب على الجميع التطوّع لمساعدة المجتمع؟', 'promptDe': 'Sollte jeder ehrenamtlich für die Gesellschaft arbeiten?', 'pro': [{'pointAr': 'يساعد المحتاجين بشكل مباشر.', 'pointDe': 'Hilft direkt den Bedürftigen.'}, {'pointAr': 'يقوّي العلاقات في المجتمع.', 'pointDe': 'Stärkt die Gemeinschaft.'}, {'pointAr': 'تجربة جيدة للسيرة الذاتية.', 'pointDe': 'Gut für den Lebenslauf.'}], 'contra': [{'pointAr': 'وقت محدود للعاملين بدوام كامل.', 'pointDe': 'Wenig Zeit bei Vollzeitjob.'}, {'pointAr': 'بعض الناس يحتاجون كل وقتهم لإعالة أسرهم.', 'pointDe': 'Manche brauchen ihre Zeit für die Familie.'}, {'pointAr': 'العمل التطوعي يجب أن يكون اختيارياً.', 'pointDe': 'Ehrenamt sollte freiwillig bleiben.'}], 'goldenPhrases': [{'de': 'Ehrenamt ist eine wichtige Säule unserer Gesellschaft.', 'ar': 'العمل التطوعي ركن مهم من أركان مجتمعنا.'}, {'de': 'Niemand sollte gezwungen werden.', 'ar': 'يجب ألاّ يُجبَر أحد.'}, {'de': 'Schon eine Stunde pro Woche kann viel bewirken.', 'ar': 'حتى ساعة أسبوعياً تُحدث فرقاً.'}, {'de': 'Ich engagiere mich seit … in …', 'ar': 'أنا أتطوّع منذ ... في ...'}], 'modelEssay': 'Ehrenamt ist eine wichtige Säule unserer Gesellschaft. Aber soll jeder dazu verpflichtet werden?\n\nAuf der einen Seite hilft Ehrenamt vielen Menschen: in Sportvereinen, bei der Tafel für Bedürftige oder in Flüchtlingsprojekten. Außerdem lernt man neue Leute kennen und sammelt Erfahrung – auch für den Beruf.\n\nAuf der anderen Seite haben nicht alle Menschen die gleiche Zeit. Eltern mit zwei Kindern und einem Vollzeitjob sind oft ausgelastet.\n\nNiemand sollte gezwungen werden. Aber jeder kann nachdenken, ob auch nur eine Stunde pro Woche möglich ist – schon das kann viel bewirken. Ich engagiere mich seit zwei Jahren in einem Sprachcafé für Geflüchtete.', 'tips': ['افتح بمكانة العمل التطوعي.', 'فرّق بين الإجبار والاختيار.', 'اختم بمثالك الشخصي.']}];
